window.__LEX={"G1":"<h1>a</h1>\n<p>Strong n° 1 <i>Prononciation [al'-fah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>première lettre de l'alphabet Grec.</li>\n<li>Christ est l'Alpha pour indiquer qu'il est le commencement et la fin.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Α</b> <b>Α, α</b> (ἄλφα) <i>indécl</i>. alpha, <i>1<sup>re</sup> lettre de l’alphabet grec ; comme chiffre</i> αʹ = 1 ͵α = 1 000.<p><b>Étym</b>. <i>cf. hébr</i>. aleph.<b>ἁ</b> <font color=\"brown\">[ᾱ]</font> <i>dor. c</i>. ἡ, <i>fém. de</i> ὁ.<b>ἅ</b> <font color=\"brown\">[ᾱ]</font> <i>dor. c</i>. ἥ, <i>fém. de</i> ὅς.<br><font color=\"brown\">[ᾰ]</font> <i>pl. neutre de</i> ὅς, <i>pron. rel. et poss</i>.<b>ἆ</b> <font color=\"brown\">[ᾱ]</font> <i>exclamation d’étonnement, de douleur, d’indignation, etc</i>. ah ! oh ! ESCHL. <i>Ag. 1087, etc. ;</i> SOPH. <i>O.R. 1147, etc. ; qqf. redoublée</i> ἆ ἆ, ESCHL. <i>Pr. 114, 566, etc. ; dans Hom. touj. jointe à</i> δειλός : ἆ δειλέ, ἆ δειλοί, ἆ δειλώ, IL. <i>11, 441 ; 17, 443 ; 11, 452, etc</i>. ah ! malheureux ! <i>rare en prose,</i> PLAT. <i>Hipp. ma. 295</i> a.</p><p><b>Étym</b>. <i>onomatopée ; cf</i>. ἄζω².<b>ᾇ</b> <i>dor. c</i>. ᾗ, <i>dat. fém. sg. de</i> ὅς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α</font> &lt; א - <font face=\"Georgia\">ἄλφα</font>\n<br><br>Origine : Hébreu TDNT – a 1</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Lettre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>  \n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (3) => <a class=\"ref\" data-r=\"REV1.8;21.6;22.13\">Apocalypse 1.8 ; 21.6 ; 22.13</a></li>\n</ul>\n</td></tr>\n</table>","G2":"<h1>Aaron</h1>\n<p>Strong n° 2 <i>Prononciation [ah-ar-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Aaron = « Haut placé, ou éclairé » = étymologie incertaine, peut signifier « Brillant »\n<ol><li>Le frère aîné de Moïse, le premier souverain sacrificateur d'Israël, dont les descendants héritèrent le sacerdoce.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ααρων</font> &lt; אהרן - <font face=\"Georgia\">Ἀαρών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>  \n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK1.5\">Luc 1.5</a></li>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT7.40\">Actes 7.40</a></li>\n<li>Hébreux (3) => <a class=\"ref\" data-r=\"HEB5.4;7.11;9.4\">Hébreux 5.4 ; 7.11 ; 9.4</a></li>\n</ul>\n</td></tr>\n</table>","G3":"<h1>Abaddon</h1>\n<p>Strong n° 3 <i>Prononciation [ab-ad-dohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ruine</li>\n<li>destruction (<a class=\"ref\" data-r=\"JOB31.12\">Job 31.12</a>)</li>\n<li>séjour des morts, tombeau (<a class=\"ref\" data-r=\"PSA88.11\">Ps 88.11</a>)</li>\n<li>abîme</li>\n<li>le nom de l'ange de l'abîme, nommé en Grec Apollyon (<a class=\"ref\" data-r=\"REV9.11\">Ap 9.11</a>) ministre de la mort, et auteur du ravage sur la terre.</li>\n<li>Schéol (gouffre qui appelle) (<a class=\"ref\" data-r=\"JON26.6\">Job 26.6</a> ; <a class=\"ref\" data-r=\"PRO11.11\">Pr 15.11</a>)</li>\n<li>mort (<a class=\"ref\" data-r=\"JOB28.22\">Job 28.22</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβαδδων</font> &lt; אבדון - <font face=\"Georgia\">Ἀβαδδών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1) => <a class=\"ref\" data-r=\"REV9.11\">Apocalypse 9.11</a></li>\n</ul>\n</td></tr>\n</table>","G4":"<h1>abares</h1>\n<p>Strong n° 4 <i>Prononciation [ab-ar-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pas onéreux</li>\n<li>pas lourd</li>\n<li>léger, sans poids</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀβαρής</b> <b>ἀ·ϐαρής, ής, ές</b> <font color=\"brown\">[ϐᾰ]</font> :<br><b> 1</b> non pesant, léger, ARSTT. <i>Cæl. 1, 8, 16, etc. ;</i><br><b> 2</b> <i>fig</i>. non désagréable, agréable, NT. <i>2Cor. 11, 9</i>.<p><b>Étym</b>. ἀ, βάρος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-βαρης - ἀβαρής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1) => <a class=\"ref\" data-r=\"2CO11.9\">2 Corinthiens 11.9</a></li>\n</ul>\n</td></tr>\n</table>","G5":"<h1>Abba</h1>\n<p>Strong n° 5 <i>Prononciation [ab-bah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abba = « père »\n<ol>\n<li>Exprime l'affection filiale envers Dieu</li>\n<li>Le mot hébreu correspondant est ab, qui se retrouve dans les noms propres (Abner, Abimélec, Eliab...)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀββᾶ</b> <b>(ὁ)</b> <i>indécl</i>. père, NT. <i>Marc. 14, 36 ; Rom. 8, 15, etc</i>.<p><b>Étym</b>. <i>mot hébreu</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αββα</font> &lt; אבא - <font face=\"Georgia\">Ἀββα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK14.36\">Marc 14.36</a></li>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM8.15\">Romains 8.15</a></li>\n<li>Galates (1) => <a class=\"ref\" data-r=\"GAL4.6\">Galates 4.6</a></li>\n</ul>\n</td></tr>\n</table>","G6":"<h1>Abel</h1>\n<p>Strong n° 6 <i>Prononciation [ab'-el]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abel = « souffle - vapeur »\n<ol><li>le second fils d'Adam, tué par son frère Caïn</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβελ</font> &lt; הבל - <font face=\"Georgia\">Ἄβελ</font>\n<br><br>Voir définition Hebel </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT 23.35\">Matthieu 23.35</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK11.51\">Luc 11.51</a></li>\n<li>Hébreux (2) => <a class=\"ref\" data-r=\"HEB11.4\">Hébreux 11.4</a></li>\n</ul>\n</td></tr>\n</table>","G7":"<h1>Abia</h1>\n<p>Strong n° 7 <i>Prononciation [ab-ee-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abia (Angl. Abijah) = « L'Eternel est un père »\n<ol>\n<li>un sacrificateur, chef d'une famille de sacrificateurs. Au 8<sup>ème</sup> rang lorsque David les a divisés en 24 classes</li>\n<li>fils et successeur de Roboam sur le trône de Juda</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβια</font> &lt; אביה - <font face=\"Georgia\">Ἀβιά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT1.7\">Matthieu 1.7</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK1.5\">Luc 1.5</a></li>\n</ul>\n</td></tr>\n</table>","G8":"<h1>Abiathar</h1>\n<p>Strong n° 8 <i>Prononciation [ab-ee-ath'-ar]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abiathar = « père de l'abondance »\n<ol><li>le nom d'un souverain sacrificateur</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβιαθαρ</font> &lt; אביתר - <font face=\"Georgia\">Ἀβιάθαρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK2.26\">Marc 2.26</a></li>\n</ul>\n</td></tr>\n</table>","G9":"<h1>Abilene</h1>\n<p>Strong n° 9 <i>Prononciation [ab-ee-lay-nay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abilène (Angl. Abilene) = « prairie »\n<ol><li>une région de Syrie entre le Liban et l'Hermon, vers la Phénicie, à 30 km de Damas et Héliopolis dans une remarquable gorge appelée « Suk Wadi Barada ».</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀβιληνή</b> <b>ῆς (ἡ)</b> Abilène, territoire d’Abiles, NT. <i>Luc. 3, 1</i>.<p><b>Étym</b>. Ἄϐιλα.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβιληνη - Ἀβιληνή</font>\n<br><br>origine étrangère, cf agora 58 Dérivé du nom de la capitale Abila, provenant lui-même de l'hébreu Abel</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK3.1\">Luc 3.1</a></li>\n</ul>\n</td></tr>\n</table>","G10":"<h1>Abioud</h1>\n<p>Strong n° 10 <i>Prononciation [ab-ee-ood']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Abiud (Angl. Abihud) = « père de l'éloge ou père loué »\n<ol><li>le fils de Béla et petit-fils de Benjamin (<a class=\"ref\" data-r=\"1CH8.3\">1Ch 8.3</a>)</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβιουδ</font> &lt; אביהוד - <font face=\"Georgia\">Ἀβιούδ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT1.13\">Matthieu 1.13</a></li>\n</ul>\n</td></tr>\n</table>","G11":"<h1>Abraam</h1>\n<p>Strong n° 11 <i>Prononciation [ab-rah-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr>\n<td>Abraham = « père d'une multitude »\n<ol><li>le fils de Térach et le fondateur de la nation Juive</li></ol>\n</td>\n</tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀβραάμ</b> <b>(ὁ)</b> <i>indécl</i>. Abraham, <i>n. hébreu,</i> ANTH. <i>1, 65</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αβρααμ</font> &lt; אברהם - <font face=\"Georgia\">Ἀβραάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n73 fois dans 69 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (15)</li>\n<li>Jean (11)</li>\n<li>Actes (7)</li>\n<li>Romains (9)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (9)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G12":"<h1>abussos</h1>\n<p>Strong n° 12 <i>Prononciation [ab'-us-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans fond</li>\n<li>infini</li>\n<li>l'abîme\n<ol type=\"a\">\n<li>la fosse</li>\n<li>l'incommensurable profondeur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄβυσσος</b> <b>ἄ·ϐυσσος, ος, ον</b>, sans fond, d’une profondeur immense, HDT. <i>2, 28 ;</i> ESCHL. <i>Suppl. 470 ; fig. en parl. de richesses, etc</i>. ESCHL. <i>Sept. 950 ;</i> AR. <i>Lys. 174, etc. ;</i> ἡ ἄϐ. abîme sans fond, NT. <i>Luc. 8, 31, etc. ; particul</i>. abîme de la mer, SPT. <i>Esaï. 44, 27</i>.<p><b>Étym</b>. ἀ, βυσσός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-βυσσος - ἄβυσσος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK8.31\">Luc 8.31</a></li>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM10.7\">Romains 10.7</a></li>\n<li>Apocalypse (7) => <a class=\"ref\" data-r=\"REV9.1;9.2;9.11;11.7;17.8;20.1;20.3\">Apocalypse 9.1 ; 9.2 ; 9.11; 11.7 ; 17.8 ; 20.1 ; 20.3</a></li>\n</ul>\n</td></tr>\n</table>","G13":"<h1>Agabos</h1>\n<p>Strong n° 13 <i>Prononciation [ag'-ab-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Agabus = « sauterelle »\n<ol><li>un prophète Chrétien</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αγαβος</font> &lt; אגבוס - <font face=\"Georgia\">Ἄγαβος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT11.28;21.10\">Actes 11.28 ; 21.10</a></li>\n</ul>\n</td></tr>\n</table>","G14":"<h1>agathoergeo</h1>\n<p>Strong n° 14 <i>Prononciation [ag-ath-er-gheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bien travailler, faire bien, agir correctement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθοεργέω</b> <b>ἀγαθοεργέω-ῶ</b> <font color=\"brown\">[ᾰᾰ]</font> faire le bien <i>ou</i> du bien, NT. <i>1Tim. 6, 18 ; au pass</i>. CLÉM. <i>1, 200 c Migne</i>.<p><b>➼</b> <i>Par contr</i>. ἀγαθουργέω-ῶ, NT. <i>Ap. 14, 17</i>.</p><p><b>Étym</b>. ἀγαθοεργός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθο-εργεω - ἀγαθοεργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1) => <a class=\"ref\" href=\"r.php?v=LSS&r=1TI6.18\">1 Timothée 6.18</li>\n</ul>\n</td></tr>\n</table>","G15":"<h1>agathopoieo</h1>\n<p>Strong n° 15 <i>Prononciation [ag-ath-op-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire le bien, faire quelque chose qui profite aux autres\n<ol type=\"a\">\n<li>être d'un bon secours aux autres</li>\n</ol>\n</li>\n<li>faire bien, agir droitement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθοποιέω</b> <b>ἀγαθοποιέω-ῶ</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> faire le bien, NT. <i>1Petr. 2, 15 et 20 ; 3, 6 et 17 ;</i><br><b> 2</b> faire du bien à, <i>acc</i>. NT. <i>Luc. 6, 33 ; dat</i>. SPT. <i>1Macc. 11, 33 ; double acc</i>. SPT. <i>Num. 10, 32</i>.<p><b>Étym</b>. ἀγαθοποιός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθοποιεω - ἀγαθοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK3.4\">Marc 3.4</a></li>\n<li>Luc (3) => <a class=\"ref\" data-r=\"LUK6.9;6.33;6.35\">Luc 6.9 ; 6.33 ; 6.35</a></li>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT14.17\">Actes 14.17</a></li>\n<li>1 Pierre (4) => <a class=\"ref\" data-r=\"1PE2.15;2.20;3.6;3.17\">1 Pierre 2.15 ; 2.20 ; 3.6 ; 3.17</a></li>\n<li>3 Jean (1) => <a class=\"ref\" data-r=\"3JN1.11\">3 Jean 1.11</a></li>\n</ul>\n</td></tr>\n</table>","G16":"<h1>agathopoiia</h1>\n<p>Strong n° 16 <i>Prononciation [ag-ath-op-oy-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le service d'une action correcte, vertu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθοποιΐα</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰγᾰ]</font> action de faire le bien, NT. <i>1Petr. 4, 19</i>.<p><b>Étym</b>. ἀγαθοποιός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθο-ποιια - ἀγαθοποιΐα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE4.19\">1 Pierre 4.19</a></li>\n</ul>\n</td></tr>\n</table>","G17":"<h1>agathopoios</h1>\n<p>Strong n° 17 <i>Prononciation [ag-ath-op-oy-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ceux qui agissent droitement, qui font le bien, vertueux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθοποιός</b> <b>ἀγαθο·ποιός, ός, όν</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> qui fait le bien, SPT. <i>Sir. 42, 14 ;</i> NT. <i>1Petr. 2, 14 ;</i><br><b> 2</b> qui fait du bien, bienfaisant, PLUT. <i>M. 368</i> b ;<br><b> 3</b> <i>t. d’astrol</i>. de bon augure, PTOL. <i>Tetr. 19, 48 ;</i> ARTÉM. <i>374 Reiff</i>.<p><b>Étym</b>. ἀγαθός, ποιέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθο-ποιος - ἀγαθοποιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE2.14\">1 Pierre 2.14</a></li>\n</ul>\n</td></tr>\n</table>","G18":"<h1>agathos</h1>\n<p>Strong n° 18 <i>Prononciation [ag-ath-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de bonne constitution ou nature</li>\n<li>utile, salutaire</li>\n<li>bon, agréable, plaisant, joyeux, heureux</li>\n<li>excellent, distingué</li>\n<li>droit, honorable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθός</b> <b>ή, όν</b> <font color=\"brown\">[ᾰᾰ]</font> bon, de bonne qualité :<br><b>   I</b> <i>en parl. de pers. :</i><br><b> 1</b> noble, de bonne naissance, IL. <i>21, 109 ; joint à</i> ἀφνειός, IL. <i>13, 664 ; à</i> εὐγενής, SOPH. <i>fr. 649 ; p. opp. à</i> χέρηες, OD. <i>15, 324 ; à</i> ἀγενής, SOPH. <i>fr. 105 ; en parl. de l’origine, du sang,</i> OD. <i>4, 611, etc. :</i> καλοὶ καὶ ἀγ. ἄνδρες, PLUT. <i>Dem. 4,</i> gens de bonne famille (<i>lat</i>. optimates) ;<br><b> 2</b> brave, IL. <i>1, 131, etc. ;</i> HDT. <i>5, 109, etc. ;</i><br><b> 3</b> bon, accompli en son genre : ἀγ. βασιλεύς, IL. <i>3, 179 ;</i> θεράπων, IL. <i>16, 65, etc</i>. bon roi, bon serviteur ; <i>souv. avec un détermin</i>. βοὴν ἀγ. IL. <i>2, 408,</i> qui a une voix retentissante ; ἀγ. γνώμην, SOPH. <i>O.R. 687,</i> de bon conseil ; ἀγ. τὰ πολιτικά, PLAT. <i>Gorg. 516</i> b, qui s’entend aux choses du gouvernement ; <i>avec une prép</i>. ἀγ. ἐν πολέμῳ, XÉN. <i>Œc. 4, 15,</i> propre à la guerre ; ἀγ. εἴς τι, PLAT. <i>1 Alc. 125</i> a ; πρός τι, PLAT. <i>Rsp. 407</i> e ; περί τι, LYS. <i>130, 2,</i> bon pour qqe ch., propre à qqe ch. ; ἀγ. κατὰ πάντα, THC. <i>4, 81,</i> propre à tout ; <i>avec un inf</i>. ἀγ. μάχεσθαι, HDT. <i>1, 135,</i> propre à combattre ;<br><b> 4</b> bon, <i>au sens mor</i>. THC. <i>1, 37, etc. ;</i> οἱ καλοὶ καὶ ἀγαθοί, PLUT. <i>Cic. 11,</i> les bons citoyens ; <i>surt. chez les philos</i>. PLAT. <i>Def. 415</i> d, <i>Rsp. 409</i> c, <i>etc. ; qqf. ironiq</i>. bon, honnête, simple, THC. <i>3, 82 ; souv. joint à d’autres adj</i>. σοφὸς κἀγαθός, SOPH. <i>Ph. 119,</i> sage et bon ; δίκαιος κἀγ. SOPH. <i>Ph. 1050,</i> juste et bon ; <i>surt</i>. καλὸς κἀγ. ATT. beau et bon, <i>càd</i>. parfait ; ὦ ἀγαθέ, ὦ 'γαθέ, ATT. (PLAT. <i>Prot. 311</i> a, <i>etc</i>.) mon bon ! <i>souv. avec une nuance d’ironie ;</i><br><b> 5</b> favorable, propice, bienveillant, <i>en un sens religieux :</i> ὁ ἀγ. δαίμων, AR. <i>Vesp. 525,</i> le bon génie ; ἡ θεὸς ἀγαθή, PLUT. <i>Cæs. 9, etc</i>. la bonne déesse (<i>lat</i>. bona dea) <i>à Rome ;</i> ἀγαθῇ τύχῃ, PLUT. <i>Dem. 20,</i> à la fortune propice (<i>v</i>. τύχη) ;<br><b>   II</b> <i>en parl. de choses :</i><br><b> 1</b> bon, accompli en son genre : δαὶς ἀγαθή, OD. <i>15, 506,</i> bon repas ; Ἰθάκη, ἀγαθὴ κουροτρόφος, OD. <i>9, 27,</i> Ithaque, bonne nourricière de jeunes garçons ;<br><b> 2</b> qui convient à, utile à : ἀ. ἀνδρί, OD. <i>17, 352,</i> qui convient à un homme ; ἀ. τῇ πόλει, XÉN. <i>Cyn. 18, 17,</i> utile à l’État ; <i>qqf. avec le gén</i>. ἀγαθὸν πυρετοῦ, XÉN. <i>Mem. 3, 8, 3</i> (remède) bon contre la fièvre ; ἀγαθόν (ἐστι) <i>avec l’inf</i>. IL. <i>7, 282, etc</i>. ATT. il est bon de, <i>etc. ; abs</i>. εἰπεῖν <i>ou</i> μυθεῖσθαι εἰς ἀγαθόν, IL. <i>9, 102 ;</i> εἰς ἀγαθά, IL. <i>23, 305,</i> parler pour le bien ;<br><b> 3</b> propice, favorable : ἀγαθὴ ἡμέρα, XÉN. <i>Œc. 11,</i> jour favorable pour faire qqe ch. ;<br><b> 4</b> prospère, heureux : ἀγαθόν τι πράττειν, XÉN. <i>Œc. 12,</i> prospérer ;<br><b>   III</b> <i>subst</i>. τὸ ἀγαθόν :<br><b> 1</b> bien, bienfait, ATT. ; ἐπ' ἀγαθῷ τινος, THC. <i>5, 27, etc., ou</i> τινι, AR. <i>Ran. 1487,</i> pour le bien de qqn ;<br><b> 2</b> ce qui est bon, un bien, ATT. ; <i>particul. dans la doctr. stoïc</i>. EPICT. <i>Ench. 24, 3 ; 25, 1, etc. ; en parl. de pers</i>. φίλον, μέγιστον ἀγαθόν, XÉN. <i>Mem. 2, 4, 2,</i> un ami, le plus grand bien ; <i>abs</i>. le bien en soi, <i>t. de phil</i>. PLAT. <i>Phæd. 76</i> d, <i>Rsp. 506</i> b, <i>508</i> e, <i>etc. ;</i> τὰ ἀγαθά, les biens, la fortune, la puissance, HDT. <i>2, 172 ;</i> PLAT. <i>Leg. 661</i> a, <i>697</i> b, <i>etc. ; ou</i> les qualités physiques et morales, PLAT. <i>Leg. 697</i> b ; <i>particul</i>. les biens de la terre, THC. <i>1, 82 ; 2, 58, etc</i>.<br><i>● Cp. et Sup. (v. chacun des mots suiv. à son ordre alphab.) :</i><br>    ◊ ἀμείνων, <i>sans Sup</i>.,<br>    ◊ <i>poét</i>. ἀρείων, ἄριστος,<br>    ◊ βελτίων, <i>poét</i>. βέλτερος ; βέλτιστος, <i>poét</i>. βέλτατος,<br>    ◊ κρείσσων ; κράτιστος, <i>poét</i>. κάρτιστος,<br>    ◊ λωΐων, <i>att</i>. λῴων, <i>poét</i>. λωΐτερος ; λώϊστος <i>ou</i> λῷστος,<br>    ◊ <i>poét</i>. φέρτερος ; <i>poét</i>. φέρτατος <i>et</i> φέριστος,<br>    ◊ <i>cp. et sup. directs, réc. et rares :</i> ἀγαθώτερος, SPT. <i>Judith 11, 25 ; 15, 2 ;</i> ἀγαθώτατος, DS. <i>16, 85 ;</i> HLD. <i>5, 15</i>.<p><b>➼</b> <i>Crase de l’art. et de l’adj. dans</i> ὦγαθέ = ὦ ἀγαθέ, THCR. <i>Idyl. 14, 8 ;</i> ἁγαθοί <font color=\"brown\">[ᾱᾰ]</font> = οἱ ἀγαθοί, τἀγαθόν <font color=\"brown\">[ᾱᾰ]</font> = τὸ ἀγαθόν, τἀγαθοῦ <font color=\"brown\">[ᾱᾰ]</font> = τοῦ ἀγαθοῦ, ATT. <i>Éol</i>. ἄγαθος, THCR. <i>Idyl. 29, 21 ; d’où par crase</i> ὥγαθος = ὁ ἀγ. THCR. <i>Idyl. 30, 83 ; lac</i>. ἀγασώς, AR. <i>Lys. 1301</i>.</p><p><b>Étym</b>. <i>incert</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθος - ἀγαθός</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n101 fois dans 90 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (3)</li>\n<li>Luc (16)</li>\n<li>Jean (3)</li>\n<li>Actes (3)</li>\n<li>Romains (21)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (4)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (7)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G19":"<h1>agathosune</h1>\n<p>Strong n° 19 <i>Prononciation [ag-ath-o-soo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>droiture de cœur et de vie, bonté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαθωσύνη</b> <b>ης (ἡ)</b> <font color=\"brown\">[ᾰᾰ]</font> bonté, bienveillance, SPT. <i>2Par. 24, 16, etc. ;</i> NT. <i>Rom. 15, 14, etc</i>.<p><b>Étym</b>. ἀγαθόω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαθωσυνη - ἀγαθωσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM15.14\">Romains 15.14</a></li>\n<li>Galates (1) => <a class=\"ref\" data-r=\"GAL5.22\">Galates 5.22</a></li>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH5.9\">Éphésiens 5.9</a></li>\n<li>2 Thessaloniciens (1) => <a class=\"ref\" data-r=\"2TH1.11\">2 Thessaloniciens 1.11</a></li>\n</ul>\n</td></tr>\n</table>","G20":"<h1>agalliasis</h1>\n<p>Strong n° 20 <i>Prononciation [ag-al-lee'-as-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>joie extrême, allégresse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαλλίασις</b> <b>εως (ἡ)</b> <font color=\"brown\">[ᾰγιᾱ]</font> <i>c</i>. ἀγαλλίαμα, SPT. <i>Tob. 13, 1, etc. ;</i> NT. <i>Luc. 1, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαλλιασις - ἀγαλλίασις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2) => <a class=\"ref\" data-r=\"LUK1.14;44\">Luc 1.14 ; 44</a></li>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT2.46\">Actes 2.46</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB1.9\">Hébreux 1.9</a></li>\n<li>Jude (1) => <a class=\"ref\" data-r=\"JUD1.24\">Jude 24</a></li>\n</ul>\n</td></tr>\n</table>","G21":"<h1>agalliao</h1>\n<p>Strong n° 21 <i>Prononciation [ag-al-lee-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>exulter, se réjouir fortement, être extrêmement heureux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγαλλιάω</b> <b>ἀγαλλιάω-ῶ</b> (<i>seul. prés. et ao</i>. ἠγαλλίασα) se réjouir, NT. <i>Luc. 1, 47 ;</i><br><b>Moy. ἀγαλλιάομαι-ῶμαι</b> <font color=\"darkgreen\">(<i>f</i>. -ιάσομαι, <i>ao</i>. ἠγαλλιασάμην <i>ou</i> -άσθην)</font> se réjouir : τι, SPT. <i>Tob. 13, 7 ;</i> τινι, SPT. <i>Ps. 94, 1 ;</i> ἔν τινι, <i>ibid. 32, 1 ;</i> ἐπί τινι, <i>ibid. 34, 9 ;</i> ἐπί τι, <i>ibid. 118, 161,</i> de qqe ch. ; <i>avec un inf</i>. SPT. <i>Ps. 18, 16,</i> de faire qqe ch.<p><b>Étym</b>. ἀγάλλομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγαλλιαω - ἀγαλλιάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n<li>1 Pierre (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G22":"<h1>agamos</h1>\n<p>Strong n° 22 <i>Prononciation [ag'-am-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non marié, célibataire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγαμος</b> <b>ἄ·γαμος, ος, ον</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> non marié, célibataire <i>ou</i> veuf, <i>en parl. de l’homme</i> (ἄνανδρος <i>en parl. de la femme</i>) IL. <i>3, 40 ;</i> ATT. ; <i>en parl. de la femme,</i> ESCHL. <i>Suppl. 143 ;</i> SOPH. <i>O.R. 1502, Ant. 867, etc. ;</i><br><b> 2</b> γάμος ἄγ. SOPH. <i>O.R. 1214 ;</i> EUR. <i>Hel. 690,</i> union qui n’en est pas une, union funeste.<p><b>Étym</b>. ἀ, γάμος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-γαμος - ἄγαμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G23":"<h1>aganakteo</h1>\r\n<p>Strong n° 23 <i>Prononciation [ag-an-ak-teh'-o]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>Etre indigné, rempli d'indignation, être dans un grand déplaisir</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγανακτέω</b> <b>ἀγανακτέω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ἠγανάκτουν, <i>f</i>. ἀγανακτήσω, <i>ao</i>. ἠγανάκτησα)</font> <font color=\"brown\">[ᾰᾰν]</font> <i>litt</i>. s’emporter, <i>d’où :</i><br><b> 1</b> bouillonner, fermenter, <i>en parl. du vin,</i> PLUT. <i>M. 734</i> e ; <i>fig. en parl. de l’âme,</i> PLAT. <i>Phædr. 251</i> c ; <i>p. ext</i>. être vivement excité <i>ou</i> irrité, <i>en parl. de sensations physiques (agacement des dents, etc</i>.) HPC. <i>426, 6 ;</i> DIOSC. <i>5, 84 ;</i><br><b> 2</b> <i>p. suite,</i> s’indigner, s’irriter, PLAT. <i>Phæd. 117</i> d, <i>etc. ;</i> τινι, PLAT. <i>Phæd. 63</i> b ; τι, PLAT. <i>Phæd. 64</i> a ; ἐπί τινι, LYS. <i>91, 5, etc. ;</i> ὑπέρ τινος, PLAT. <i>Euthyd. 283</i> d ; περί τινος, PLAT. <i>Ep. 349</i> d ; διά τι, PLAT. <i>Phæd. 63</i> c ; πρός τι, NT. <i>Marc. 14, 4 ;</i> EPICT. <i>Ench. 4,</i> s’irriter <i>ou</i> s’indigner de qqe ch. ; <i>avec un part</i>. PLAT. <i>Phæd. 62</i> e, s’indigner de ce que ; ἀγ. εἰ, AND. <i>18, 16 ; ou</i> ἐάν, PLAT. <i>Lach. 194</i> a ; <i>ou</i> ὅτι, ANT. <i>126, 5 ; ou</i> ὡς, ATT. s’indigner de ce que ; <i>avec un rég. de pers. :</i> ἀγ. τινι, XÉN. <i>Hell. 5, 3, 11 ;</i> πρός τινα, PLUT. <i>Cam. 28 ;</i> κατά τινος, LUC. <i>Tim. 18,</i> s’irriter <i>ou</i> s’indigner contre qqn ;<br><b>Moy. ἀγανακτέομαι-οῦμαι</b>, <i>m. sign</i>. LUC. <i>Somn. 4</i>.<p><b>Étym</b>. <i>incert</i>.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγανακτεω - ἀγανακτέω</font>\r\n<br><br>Vient de agan (beaucoup) et achthos (chagrin, allié à )</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Verbe</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>7 fois dans 7 versets de 3 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (3) => <a class=\"ref\" data-r=\"MAT20.24;21.15;26.8\">Matthieu 20.24 ; 21.15 ;26.8</a></li>\r\n<li>Marc (3) => <a class=\"ref\" data-r=\"MRK10.14,41;14.4\">Marc 10.14,41 ; 14.4</a></li>\r\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK13.14\">Luc 13.14</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G24":"<h1>aganaktesis</h1>\r\n<p>Strong n° 24 <i>Prononciation [ag-an-ak'-tay-sis]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>indignation, irritation, vexation</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγανάκτησις</b> <b>εως (ἡ)</b> <font color=\"brown\">[ᾰᾰν]</font> :<br><b> 1</b> irritation, agacement (des dents, des gencives, <i>etc</i>.) PLAT. <i>Phædr. 251</i> c ;<br><b> 2</b> sujet d’irritation, d’indignation, THC. <i>2, 41</i>.<p><b>Étym</b>. ἀγανακτέω.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγανακτησις - ἀγανάκτησις</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom féminin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>1 fois dans 1 verset de 1 livre biblique (NT)\r\n<ul>\r\n<li>2 Corinthiens (1) => <a class=\"ref\" data-r=\"2CO7.11\">2 Corinthiens 7.11</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G25":"<h1>agapao</h1>\r\n<p>Strong n° 25 <i>Prononciation [ag-ap-ah'-o]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>des personnes\r\n<ol type=\"a\">\r\n<li>accueillir, recevoir, aimer chèrement</li>\r\n</ol>\r\n</li>\r\n<li>des choses\r\n<ol type=\"a\">\r\n<li>en avoir plaisir, être content d'une chose, d'un objet</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγαπάω</b> <b>ἀγαπάω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. ήσω, <i>ao</i>. ἠγάπησα, <i>pf</i>. ἠγάπηκα ; <i>pass. pf</i>. ἠγάπημαι)</font> <font color=\"brown\">[ᾰγᾰ]</font> :<br><b> 1</b> <i>avec un rég. de pers</i>. accueillir avec amitié, traiter avec affection, <i>acc</i>. OD. <i>23, 214 ;</i> ἀγ. νεκρούς, EUR. <i>Suppl. 764,</i> rendre les derniers devoirs à des morts ;<br><b> 2</b> <i>p. ext. avec un rég. de pers. ou de chose,</i> aimer, chérir (ses enfants, PLAT. <i>Rsp. 330</i> c ; la justice, <i>etc</i>. PLAT. <i>Phil. 62</i> d, <i>Rsp. 359</i> a, <i>etc</i>.); <i>rar</i>. aimer d’amour (<i>c</i>. ἐράω) PLUT. <i>M. 505</i> f ; LUC. <i>J. tr. 2 ;</i><br><b> 3</b> avoir une préférence pour : ἀγ. τι ἀντί τινος, DÉM. <i>263, 6 ; ou</i> πρό τινος, PLUT. <i>Cam. 10,</i> préférer une chose à une autre ; <i>d’où</i> être satisfait de : τι, DÉM. <i>70, 20 ;</i> τινι, LYS. <i>192, 26 ;</i> DÉM. <i>13, 11,</i> de qqe ch. ; ὅτι, THC. <i>6, 36 ; ou</i> ὅ, OD. <i>21, 289,</i> être satisfait que <i>ou</i> de ce que ; εἰ, PLAT. <i>Rsp. 450</i> a ; ἐάν, <i>ibid. 330</i> b ; ἤν, AR. <i>Vesp. 684, etc</i>. être satisfait si ; <i>avec un part</i>. ἀγαπῶ τιμώμενος, PLAT. <i>Rsp. 475</i> b, je suis satisfait d’être honoré ; <i>avec un inf</i>. DÉM. <i>1276, 28 ;</i> ARSTT. <i>Œc. 2, 14, etc. ; abs</i>. LYCURG. <i>157, 5</i>.<p><b>➼</b> <i>Inf. prés. dor</i>. ἀγαπῆν, STOB. <i>Fl. 85, 17 ; impf. éol</i>. ἠγάπευν, THCR. <i>Epigr. 19</i>.</p><p><b>Étym</b>. <i>inconnue</i> ou apparenté à ἄγαμαι.<br><i><b><font color=\"darkorange\">Par.</font></b></i> φιλέω..</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγαπαω - ἀγαπάω</font>\r\n<br><br>Vient peut-être de agan (beaucoup) (ou cf )</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Verbe</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>142 fois dans 109 versets de 21 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (8)</li>\r\n<li>Marc (5)</li>\r\n<li>Luc (13)</li>\r\n<li>Jean (37)</li>\r\n<li>Romains (8)</li>\r\n<li>1 Corinthiens (2)</li>\r\n<li>2 Corinthiens (4)</li>\r\n<li>Galates (2)</li>\r\n<li>Éphésiens (10)</li>\r\n<li>Colossiens (2)</li>\r\n<li>1 Thessaloniciens (2)</li>\r\n<li>2 Thessaloniciens (2)</li>\r\n<li>2 Timothée (2)</li>\r\n<li>Hébreux (2)</li>\r\n<li>Jacques (3)</li>\r\n<li>1 Pierre (4)</li>\r\n<li>2 Pierre (1)</li>\r\n<li>1 Jean (28)</li>\r\n<li>2 Jean (2)</li>\r\n<li>3 Jean (1)</li>\r\n<li>Apocalypse (4)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G26":"<h1>agape</h1>\r\n<p>Strong n° 26 <i>Prononciation [ag-ah'-pay]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>amour fraternel, affection, bonne volonté, bienveillance</li>\r\n<li>fêtes de l'amitié</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγάπη</b> <b>ης (ἡ)</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> affection, SPT. <i>Eccl. 9, 1 ; particul</i>. amour fraternel, NT. <i>1Cor. 13, 1 ;</i> amour divin, PHIL. <i>1, 283 ;</i> NT. <i>Luc. 11, 42 ; 2Cor. 5, 14 ; rar</i>. amour <i>au sens de</i> passion, SPT. <i>Cant. 2, 4, 5 ; titre d’honneur</i> (Votre Amour) BAS. <i>4, 381 ;</i> NYSS. <i>3, 1073 edd. Migne ;</i><br><b> 2</b> objet d’affection, être aimé, SPT. <i>Cant. 2, 7 ;</i><br><b> 3</b> <i>au pl</i>. agapes, repas fraternels des premiers chrétiens, NT. <i>2Petr. 2, 13, etc. ; au sg</i>. CLÉM. <i>1, 384, 1112 Migne</i>.\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγαπη - ἀγάπη</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom féminin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>116 fois dans 106 versets de 24 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (1)</li>\r\n<li>Luc (1)</li>\r\n<li>Jean (7)</li>\r\n<li>Romains (9)</li>\r\n<li>1 Corinthiens (14)</li>\r\n<li>2 Corinthiens (9)</li>\r\n<li>Galates (3)</li>\r\n<li>Ephésiens (10)</li>\r\n<li>Philippiens (4)</li>\r\n<li>Colossiens (5)</li>\r\n<li>1 Thessaloniciens (5)</li>\r\n<li>2 Thessaloniciens (3)</li>\r\n<li>1 Timothée (5)</li>\r\n<li>2 Timothée (4)</li>\r\n<li>Tite (1)</li>\r\n<li>Philémon (3)</li>\r\n<li>Hébreux (2)</li>\r\n<li>1 Pierre (3)</li>\r\n<li>2 Pierre (1)</li>\r\n<li>1 Jean (18)</li>\r\n<li>2 Jean (2)</li>\r\n<li>3 Jean (1)</li>\r\n<li>Jude (3)</li>\r\n<li>Apocalypse (2)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G27":"<h1>agapetos</h1>\r\n<p>Strong n° 27 <i>Prononciation [ag-ap-ay-tos']</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>bien-aimé, estimé, cher, favori, digne d'amour</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγαπητός</b> <b>ή, όν</b> <font color=\"brown\">[ᾰᾰ]</font> :<br><b> 1</b> aimé, chéri, <i>particul. en parl. d’un fils unique,</i> IL. <i>6, 401 ;</i> OD. <i>2, 365 ;</i> DÉM. <i>567, 24, etc. ; en parl. de choses,</i> aimable, désirable, cher, PLAT. <i>1 Alc. 131</i> e ; τὸ ἀγαπητόν, ARSTT. <i>Rhet. 1, 7, 41,</i> objet de désir ;<br><b> 2</b> <i>p. suite,</i> désiré, souhaité, <i>d’où</i> bienvenu : ἀγαπητόν (ἐστιν) εἰ <i>ou</i> ἐάν, XÉN. <i>Œc. 8, 16 ;</i> PLAT. <i>Prot. 328</i> a, <i>etc</i>. on doit s’estimer heureux si, <i>etc. ; ou avec l’inf</i>. ARSTT. <i>Nic. 9, 10, 6,</i> on doit être heureux que, <i>etc</i>.<br><i>● Sup</i>. -ότατος, PLAT. <i>Phil. 61</i> e.<p><b>➼</b> <i>Dor</i>. ἀγαπατός <font color=\"brown\">[ᾰᾰᾱ]</font> PD. <i>N. 8, 4</i>.</p><p><b>Étym</b>. ἀγαπάω.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγαπτος - ἀγαπητός</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Adjectif</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>61 fois dans 60 versets de 21 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (3)</li>\r\n<li>Marc (3)</li>\r\n<li>Luc (3)</li>\r\n<li>Actes (1)</li>\r\n<li>Romains (7)</li>\r\n<li>1 Corinthiens (4)</li>\r\n<li>2 Corinthiens (2)</li>\r\n<li>Éphésiens (2)</li>\r\n<li>Philippiens (3)</li>\r\n<li>Colossiens (4)</li>\r\n<li>1 Thessaloniciens (1)</li>\r\n<li>1 Timothée (1)</li>\r\n<li>2 Timothée (1)</li>\r\n<li>Philémon (2)</li>\r\n<li>Hébreux (1)</li>\r\n<li>Jacques (3)</li>\r\n<li>1 Pierre (2)</li>\r\n<li>2 Pierre (6)</li>\r\n<li>1 Jean (5)</li>\r\n<li>3 Jean (4)</li>\r\n<li>Jude (3)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G28":"<h1>Hagar</h1>\r\n<p>Strong n° 28 <i>Prononciation [ag'-ar]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>Agar (Angl. Hagar) = « fuite »\r\n<ol><li>concubine d'Abraham et mère d'Ismaël</li></ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>Ἄγαρ</b> <b>(ἡ)</b> <i>indécl</i>. Agar, <i>n. de f. hébreu,</i> SPT. <i>Gen. 16, 1</i>.\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">Αγαρ</font> &lt; הגר - <font face=\"Georgia\">Ἄγαρ</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom propre féminin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>2 fois dans 2 versets de 1 livre biblique (NT)\r\n<ul>\r\n<li>Galates (2) => <a class=\"ref\" data-r=\"GAL4.24,25\">Galates 4.24, 25</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G29":"<h1>aggareuo</h1>\r\n<p>Strong n° 29 <i>Prononciation [ang-ar-yew'-o]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>envoyer un courrier, dépêcher un messager à cheval, forcer à aller</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγγαρεύω</b> <font color=\"darkgreen\">(<i>f</i>. εύσω, <i>ao</i>. ἠγγάρευσα, <i>pf. inus</i>.)</font> <font color=\"brown\">[γᾰ]</font> requérir pour une corvée, <i>d’où</i> contraindre, <i>en gén., acc</i>. NT. <i>Matth. 5, 41 ; 27, 32 ; Marc. 15, 21 ;</i> JOS. <i>A.J. 13, 2, 3 ; au pass</i>. être requis, MÉN. <i>4, 201 Meineke</i>.<p><b>Étym</b>. ἄγγαρος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγγαρευω - ἀγγαρεύω</font>\r\n<br><br>origine étrangère, cf </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Verbe</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>3 fois dans 3 versets de 2 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT5.41;27.32\">Matthieu 5.41 ; 27.32</a></li>\r\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK15.21\">Marc 15.21</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G30":"<h1>aggeion</h1>\r\n<p>Strong n° 30 <i>Prononciation [ang-eye'-on]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>un vase, réceptacle, un seau, un réservoir</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγγεῖον</b> <b>ου (τὸ) :<br>   I</b> vase <i>ou</i> vaisseau <i>pour les liquides ou les matières sèches (eau, vin, blé, etc</i>.) HDT. <i>1, 188, etc. ;</i> THC. <i>4, 4 ;</i> PLAT. <i>Pol. 287</i> e, <i>etc. ; p. ext</i>. récipient, réservoir, XÉN. <i>Œc. 9, 2 ;</i> PLAT. <i>Criti. 111</i> a, <i>Leg. 845</i> e ; <i>particul</i>. récipient cylindrique, corps de pompe, PHIL. BYZ. ;<br><b>   II</b> <i>p. anal. :</i><br><b> 1</b> vaisseau, (artère, veine) ARSTT. <i>H.A. 3, 20, 2 ;</i> A. GELL. <i>18, 10 ;</i> SEXT. <i>13, 1 Bkk. ;</i><br><b> 2</b> enveloppe <i>d’un organe (estomac, reins, etc</i>.) ARSTT. <i>H.A. 3, 20, 1, etc. ;</i><br><b> 3</b> capsule, <i>t. de bot</i>. TH. <i>H.P. 1, 11, 1</i>.<p><b>➼</b> <i>Ion</i>. ἀγγήϊον, HDT. <i>l. c. etc</i>.</p><p><b>Étym</b>. ἄγγος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγγειον - ἀγγεῖον</font>\r\n<br><br>Vient de aggos (un seau), cf base de </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom neutre</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>2 fois dans 2 versets de 1 livre biblique (NT)\r\n<ul>\r\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT13.48;25.4\">Matthieu 13.48 ; 25.4</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G31":"<h1>aggelia</h1>\r\n<p>Strong n° 31 <i>Prononciation [ang-el-ee'-ah]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>message, annonce, nouvelles</li>\r\n<li>une proclamation, un commandement, un ordre</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγγελία</b> <b>ας (ἡ) :<br> 1</b> annonce, nouvelle, message, HOM. <i>etc. :</i> ἀγγελίαν φέρειν, OD. <i>1, 408 ;</i> ATT. apporter une nouvelle (<i>cf</i>. ἀγγελιαφόρος) ; ἀγγελίην φάναι, ἀποφάναι, ἀπειπεῖν, IL. <i>18, 17, etc</i>. annoncer une nouvelle ; <i>avec un verbe de mouv</i>. ἀγγελίην ἐλθεῖν, IL. <i>11, 140,</i> aller annoncer, porter un message ; ἀγγελίη ἐμή, IL. <i>19, 336,</i> nouvelle me concernant ; ἀγγελίη τινός, OD. <i>1, 408 ; 10, 245 ;</i> THC. <i>8, 15 ;</i> SOPH. <i>Aj. 221,</i> nouvelle de qqn ; ἀγγελία τῶν πόλεων ὅτι, <i>etc</i>. THC. <i>1, 61,</i> la nouvelle que les villes, <i>etc</i>. (= ἀγγ. ὅτι αἱ πόλεις, <i>etc</i>.) ;<br><b> 2</b> députation, <i>à l’acc. adv</i>. ἀγγελίην, IL. <i>4, 384 ; 11, 140 ;</i><br><b> 3</b> annonce, déclaration, proclamation, PD. <i>P. 2, 41 ;</i><br><b> 4</b> ordre, commandement, OD. <i>7, 263 ;</i> HH. <i>Cer. 448 ;</i> PD. <i>O. 3, 29</i>.<p><b>➼</b> <i>Ion</i>. -ίη, HOM. <i>ll. cc. ;</i> HDT. <i>2, 114, etc</i>.</p><p><b>Étym</b>. ἄγγελος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγγελια - ἀγγελία</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom féminin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>1 fois dans 1 verset de 1 livre biblique (NT)\r\n<ul>\r\n<li>1 Jean (1) => <a class=\"ref\" data-r=\"1JN3.11\">1 Jean 3.11</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G32":"<h1>aggelos</h1>\r\n<p>Strong n° 32 <i>Prononciation [ang'-el-os]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol><li>messager, envoyé, un ange, un messager de Dieu</li></ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἄγγελος</b> <b>ου (ὁ, ἡ) :<br>   I</b> qui apporte une nouvelle :<br><b> 1</b> messager, messagère, IL. <i>1, 334, etc. ;</i> XÉN. <i>Cyr. 2, 4, 1, etc. ; au fém</i>. IL. <i>24, 561 ; en parl. d’Iris,</i> IL. <i>2, 786 ; 3, 121 ; p. anal. en parl. d’oiseaux qui annoncent des présages,</i> IL. <i>24, 292, 296 ;</i><br><b> 2</b> <i>en poésie et en prose ion</i>. envoyé, député, IL. <i>5, 804 ;</i> HDT. <i>5, 91, etc. ;</i><br><b> 3</b> <i>postér</i>. messager de Dieu, ange, SPT. <i>Tob. 5, 22 ; Job 20, 15 ; Ps. 77, 25, etc. ;</i> NT. <i>Luc. 1, 19, etc. ;</i> ὁ δορυφόρος ἄγγ. NT. <i>Matth. 18, 10 ; Luc. 12, 15,</i> l’ange gardien ;<br><b>   II</b> message, nouvelle, POL. <i>1, 72, 4</i>.<p><b>➼</b> <i>Pl. irrég</i>. τὰ ἄγγελα, NONN. <i>D. 34, 326</i>.</p><p><b>Étym</b>. <i>inconnue, p.-ê. emprunt à une langue orientale, cf</i>. ἄγγαρος.<b>Ἄγγελος</b> <b>ου (ὁ)</b> Angélos, <i>h</i>. PLUT. <i>Pyrrh. 2</i>.</p><p><b>Étym</b>. ἄγγελος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγγελος - ἄγγελος</font>\r\n<br><br>Vient de aggello (probablement dérivé de , cf ) (apporter des nouvelles)</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom masculin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>177 fois dans 173 versets de 18 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (20)</li>\r\n<li>Marc (6)</li>\r\n<li>Luc (26)</li>\r\n<li>Jean (4)</li>\r\n<li>Actes (21)</li>\r\n<li>Romains (1)</li>\r\n<li>1 Corinthiens (4)</li>\r\n<li>2 Corinthiens (2)</li>\r\n<li>Galates (3)</li>\r\n<li>Colossiens (1)</li>\r\n<li>2 Thessaloniciens (1)</li>\r\n<li>1 Timothée (2)</li>\r\n<li>Hébreux (13)</li>\r\n<li>Jacques (1)</li>\r\n<li>1 Pierre (2)</li>\r\n<li>2 Pierre (2)</li>\r\n<li>Jude (1)</li>\r\n<li>Apocalypse (67)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G33":"<h1>age</h1>\r\n<p>Strong n° 33 <i>Prononciation [ag'-eh]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>Allez ! Venez ! A vous !</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἄγε</b> <i>et</i> <b>ἄγετε</b> (<i>2 sg. et pl. impér. de</i> ἄγω) <i>interj</i>. allons ! eh bien ! voyons ! <i>avec une particule,</i> ἄγε δή, IL. <i>3, 441, etc. ;</i> XÉN. <i>Cyr. 5, 5, 15, etc. ;</i> ἀλλ' ἄγε, IL. <i>2, 331 ;</i> ESCHL. <i>Pers. 140, etc. ;</i> ἀλλ' ἄγετ', OD. <i>21, 73, etc. ;</i> ἄγε νῦν, AR. <i>Eq. 1011 ; avec un autre impér</i>. εἴπ' ἄγε, IL. <i>3, 192,</i> dis, allons !.<p><b>➼</b> ἄγε <i>d’ord. devant une 1<sup>e</sup> pl. sbj</i>. IL. <i>11, 348 ;</i> ESCHL. <i>Pers. 140 ;</i> XÉN. <i>Cyr. 5, 5, 15 ; ou une 2<sup>e</sup> pl. sbj</i>. OD. <i>3, 332 ; rar. avec une 1<sup>e</sup> sg. sbj</i>. OD. <i>20, 296, ou une 3<sup>e</sup> pl. impér</i>. IL. <i>2, 437 ;</i> ἄγετε <i>avec une 1<sup>e</sup> pl</i>. IL. <i>2, 139 ;</i> OD. <i>1, 76 ;</i> AR. <i>Lys. 665 ; rar. avec une 1<sup>e</sup> sg</i>. OD. <i>22, 139</i>.<b>ἆγε</b> <font color=\"brown\">[ᾱ]</font> <i>v</i>. ἄγω <i>et</i> ἄγνυμι.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγε - ἄγε</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Interjection</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>2 fois dans 2 versets de 1 livre biblique (NT)\r\n<ul>\r\n<li>Jacques (2) => <a class=\"ref\" data-r=\"JAS4.13;5.1\">Jacques 4.13 ; 5.1</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G34":"<h1>agele</h1>\r\n<p>Strong n° 34 <i>Prononciation [ag-el'-ay]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>troupeau ou bétail</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγέλη</b> <b>ης (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> troupeau, troupe, <i>en parl. d’animaux (troupeau de bœufs,</i> SOPH. <i>O.R. 26 ;</i> XÉN. <i>Mem. 1, 2, 32, etc. ; de porcs,</i> HÉS. <i>Sc. 168 ; troupe d’oiseaux,</i> SOPH. <i>Aj. 168 ; banc de poissons,</i> OPP. <i>H. 3, 639 ; dans Homère,</i> troupeau de bœufs, de génisses, IL. <i>11, 678, etc. ; une seule fois</i> troupe de chevaux, IL. <i>19, 281) ; p. anal</i>. troupe de personnes, PD. <i>fr. 78, etc. ; fig</i>. πόνων ἀγέλαι, EUR. <i>H.f. 1276,</i> foule d’épreuves ;<br><b> 2</b> <i>au pl., en Crète,</i> groupes <i>ou</i> sections <i>entre lesquels étaient répartis les jeunes gens à partir de 17 ans (cf</i>. βοῦαι) PLUT. <i>Lyc. 16 ;</i> HÉRACLIDE LEMB. <i>Pol. 15, p. 374 Rose</i>.<p><b>➼</b> <i>Dat. sg. épq</i>. ἀγέληφι, IL. <i>2, 480. Dor</i>. ἀγέλα, PD. <i>l. c. ;</i> THCR. <i>Idyl. 5, 141</i>.</p><p><b>Étym</b>. ἄγω.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγελη - ἀγέλη</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom féminin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>7 fois dans 7 versets de 3 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (3) => <a class=\"ref\" data-r=\"MAT8.30,31,32\">Matthieu 8.30, 31, 32</a></li>\r\n<li>Marc (2) => <a class=\"ref\" data-r=\"MRK5.11,13\">Marc 5.11, 13</a></li>\r\n<li>Luc (2) => <a class=\"ref\" data-r=\"LUK8.32,33\">Luc 8.32, 33</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G35":"<h1>agenealogetos</h1>\r\n<p>Strong n° 35 <i>Prononciation [ag-en-eh-al-og'-ay-tos]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>celui dont les ascendants ne sont pas enregistrés, sans généalogie.</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγενεαλόγητος</b> <b>ἀ·γενεαλόγητος, ος, ον</b> <font color=\"brown\">[ᾱλ]</font> sans généalogie, NT. <i>Hebr. 7, 3</i>.<p><b>Étym</b>. ἀ, γενεαλογέω.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">α-γενεαλογητος - ἀγενεαλόγητος</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Adjectif</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>1 fois dans 1 verset de 1 livre biblique (NT)\r\n<ul>\r\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB7.3\">Hébreux 7.3</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G36":"<h1>agenes</h1>\r\n<p>Strong n° 36 <i>Prononciation [ag-en-ace']</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td><ol><li>ignoble, lâche, méprisable, bas, sans famille, c.à.d basse naissance</li></ol></td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἀγενής</b> <b>ἀ·γενής, ής, ές :<br> 1</b> qui n’est pas né, non créé, PLAT. <i>Tim. 27</i> c ;<br><b> 2</b> de naissance obscure, <i>d’où</i> sans noblesse, bas, vil, SOPH. <i>fr. 105 ;</i><br><b> 3</b> sans postérité, IS. (HARP.).<p><b>Étym</b>. ἀ, γένος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">α-γενης - ἀγενής</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Adjectif</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>1 fois dans 1 verset de 1 livre biblique (NT)\r\n<ul>\r\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO1.28\">1 Corinthiens 1.28</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G37":"<h1>hagiazo</h1>\r\n<p>Strong n° 37 <i>Prononciation [hag-ee-ad'-zo]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>être vénérable ou sanctifié</li>\r\n<li>séparé des choses profanes et dédié à Dieu</li>\r\n<li>purifier\r\n<ol type=\"a\">\r\n<li>nettoyer l'extérieur</li>\r\n<li>purifier par expiation : libéré de la culpabilité du péché</li>\r\n<li>purifier l'intérieur par renouvellement de l'âme</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἁγιάζω</b> <font color=\"darkgreen\">(<i>f</i>. άσω, <i>ao</i>. ἡγίασα, <i>pf. inus. ; pass. ao</i>. ἡγιάσθην, <i>pf</i>. ἡγίασμαι)</font> <font color=\"brown\">[ᾰγ]</font> :<br><b> 1</b> sanctifier, consacrer comme saint, consacrer, ANTH. <i>App. 339 ;</i> SPT. <i>Gen. 2, 3 ; Ex. 13, 2, etc. ;</i><br><b> 2</b> souiller, SPT. <i>Deut. 22, 9</i>.<p><b>Étym</b>. ἅγιος.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγιαζω - ἁγιάζωw</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Verbe</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>28 fois dans 25 versets de 13 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (3)</li>\r\n<li>Luc (1)</li>\r\n<li>Jean (4)</li>\r\n<li>Actes (2)</li>\r\n<li>Romains (1)</li>\r\n<li>1 Corinthiens (4)</li>\r\n<li>Éphésiens (1)</li>\r\n<li>1 Thessaloniciens (1)</li>\r\n<li>1 Timothée (1)</li>\r\n<li>2 Timothée (1)</li>\r\n<li>Hébreux (7)</li>\r\n<li>1 Pierre (1)</li>\r\n<li>Apocalypse (1)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G38":"<h1>hagiasmos</h1>\r\n<p>Strong n° 38 <i>Prononciation [hag-ee-as-mos']</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>consécration, purification</li>\r\n<li>l'effet de la consécration\r\n<ol type=\"a\">\r\n<li>sanctification de cœur et de vie</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἁγιασμός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾰγ]</font> :<br><b> 1</b> sanctification, consécration, DH. <i>1, 54, 16 Reiske ;</i> SPT. <i>Judith 17, 3, etc. ;</i> NT. <i>Rom. 6, 19, 22, etc. ;</i><br><b> 2</b> lieu consacré, sanctuaire, SPT. <i>2Macc. 2, 17, etc</i>.<p><b>Étym</b>. ἁγιάζω.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγιασμος - ἁγιασμός</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Nom masculin</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>10 fois dans 10 versets de 7 livres bibliques (NT)\r\n<ul>\r\n<li>Romains (2) => <a class=\"ref\" data-r=\"ROM6.19,22\">Romains 6.19, 22</a></li>\r\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO1.30\">1 Corinthiens 1.30</a></li>\r\n<li>1 Thessaloniciens (3) => <a class=\"ref\" data-r=\"1TH4.3,4,7\">1 Thessaloniciens 4.3, 4, 7</a></li>\r\n<li>2 Thessaloniciens (1) => <a class=\"ref\" data-r=\"2TH2.13\">1 Thessaloniciens 2.13</a></li>\r\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1CO1.28\">1 Corinthiens 1.28</a></li>\r\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB12.14\">Hébreux 12.14</a></li>\r\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE1.2\">1 Pierre 1.2</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G39":"<h1>hagion</h1>\r\n<p>Strong n° 39 <i>Prononciation [hag'-ee-on]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol>\r\n<li>révérend, digne de vénération</li>\r\n<li>mis à part pour Dieu, exclusivement à Lui</li>\r\n<li>services et offrandes</li>\r\n<li>sens moral : pur, sans péché, droit, saint</li>\r\n</ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγιον - ἅγιος</font>\r\n<br><br>Voir définition </td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Adjectif</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>11 fois dans 10 versets de 1 livre biblique (NT)\r\n<ul>\r\n<li>Hébreux (11) => <a class=\"ref\" data-r=\"HEB8.2;9.1,2,3,8,12,24,25;10.19;13.11\">Hébreux 8.2 ; 9.1, 2, 3, 8,1 2, 24, 25 ; 10.19 ; 13.11</a></li>\r\n</ul>\r\n</td></tr>\r\n</table>","G40":"<h1>hagios</h1>\r\n<p>Strong n° 40 <i>Prononciation [hag'-ee-os]</i></p>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\r\n<tr><td>\r\n<ol><li>chose très sainte, consacrée, un saint</li></ol>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\r\n<tr><td colspan=\"2\">\r\n<b>ἅγιος</b> <b>α, ον</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> saint, sacré, auguste, <i>en parl. de choses, abs</i>. XÉN. <i>Hell. 3, 2, 14 ; avec un gén. :</i> Ἀφροδίτης ἱρὸν ἅγιον, HDT. <i>2, 41,</i> temple consacré à Aphrodite ; <i>cf</i>. PLAT. <i>Criti. 116</i> c ; τὸ ἅγιον, chose sainte, SPT. <i>3Reg. 8, 7 ; 1 Macc. 10, 39 ;</i> NT. <i>Matth. 7, 6 ; ou</i> lieu saint, <i>particul</i>. le Tabernacle du temple de Jérusalem, SPT. <i>Ex. 36, 1 ; 1 Macc. 10, 42, etc. ;</i> τὸ ἅγιον τοῦ ἁγίου, <i>ou</i> τὰ ἅγια τῶν ἁγίων, SPT. <i>Ex. 26, 33, etc. ;</i> NT. <i>Hebr. 9, 3, etc</i>. le saint des saints ; <i>en parl. de pers</i>. saint, pur, pieux, AR. <i>Av. 522 ;</i><br><b> 2</b> <i>en mauv. part,</i> consacré aux dieux infernaux, <i>d’où</i> maudit, exécrable (<i>cf. lat</i>. sacer) CRAT. (<i>Com. fr. 2, 188</i>).<br><i>● Cp</i>. -ώτερος, PLAT. <i>Crit. 51</i> a ; <i>● Sup</i>. -ώτατος, PLAT. <i>Leg. 729</i> e, <i>etc</i>.<p><b>➼</b> <i>Inus. dans Hom. et Hés. ; chez les Trag</i>. ἁγνός.</p><p><b>Étym</b>. <i>R. indo-europ</i>. *Hieh₂ǵ- <i>et suff</i>. *-iHo-, sacrifice ; <i>apparenté à</i> ἅζομαι.</p>\r\n</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\r\n<tr><td><font face=\"Georgia\">αγιος - ἅγιος</font>\r\n<br><br>Vient de hagos (chose terrible) (cf , )</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\r\n<tr><td>Adjectif</td></tr>\r\n</table>\r\n<table class=\"border\">\r\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\r\n<tr><td>\r\n<br>222 fois dans 213 versets de 23 livres bibliques (NT)\r\n<ul>\r\n<li>Matthieu (10)</li>\r\n<li>Marc (7)</li>\r\n<li>Luc (19)</li>\r\n<li>Jean (5)</li>\r\n<li>Actes (54)</li>\r\n<li>Romains (20)</li>\r\n<li>1 Corinthiens (12)</li>\r\n<li>2 Corinthiens (8)</li>\r\n<li>Éphésiens (15)</li>\r\n<li>Philippiens (3)</li>\r\n<li>Colossiens (6)</li>\r\n<li>1 Thessaloniciens (5)</li>\r\n<li>2 Thessaloniciens (1)</li>\r\n<li>1 Timothée (1)</li>\r\n<li>2 Timothée (2)</li>\r\n<li>Tite (1)</li>\r\n<li>Philémon (2)</li>\r\n<li>Hébreux (8)</li>\r\n<li>1 Pierre (8)</li>\r\n<li>2 Pierre (5)</li>\r\n<li>1 Jean (1)</li>\r\n<li>Jude (4)</li>\r\n<li>Apocalypse (25)</li>\r\n</ul>\r\n</td></tr>\r\n</table>","G41":"<h1>hagiotes</h1>\n<p>Strong n° 41 <i>Prononciation [hag-ee-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sainteté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγιότης</b> <b>ητος (ἡ)</b> <font color=\"brown\">[ᾰ]</font> sainteté. <font color=\"darkblue\">SEPT</font> pureté morale, intention pure.<p><b>Étym</b>. ἅγιος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγιοτης - ἁγιότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB12.10\">Hébreux 12.10</a></li>\n</ul>\n</td></tr>\n</table>","G42":"<h1>hagiosune</h1>\n<p>Strong n° 42 <i>Prononciation [hag-ee-o-soo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>majesté, sainteté</li>\n<li>pureté morale</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγιωσύνη</b> <b>ης (ἡ)</b> <font color=\"brown\">[ᾰ]</font> sainteté, SPT. <i>2Macc. 3, 12 ;</i> NT. <i>Rom. 1, 4, etc</i>. <font color=\"darkblue\">SEPT</font> consécration.<p><b>Étym</b>. ἅγιος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγιωσυνη - ἁγιωσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM1.4\">Romains 1.4</a></li>\n<li>2 Corinthiens (1) => <a class=\"ref\" data-r=\"2CO7.1\">2 Corinthiens 7.1</a></li>\n<li>1 Thessaloniciens (1) => <a class=\"ref\" data-r=\"1TH3.13\">1 Thessaloniciens 3.13</a></li>\n</ul>\n</td></tr>\n</table>","G43":"<h1>agkale</h1>\n<p>Strong n° 43 <i>Prononciation [ang-kal'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la courbe ou l'angle intérieur du bras, le bras plié</li>\n<li>quelque chose d'enfermé, comme les bras de la mer, etc.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγκάλη</b> <b>ης (ἡ)</b> <font color=\"brown\">[κᾰ]</font> objet recourbé :<br><b> 1</b> bras recourbé, <i>au pl. :</i> ἐν ταῖς ἀγκάλαις περιφέρειν, XÉN. <i>Cyr. 7, 5, 50, ou</i> ἀγκάλαις περιφέρειν, EUR. <i>Or. 464,</i> porter dans ses bras ; <i>de même</i> ἀγκάλαις ἔχειν, EUR. <i>I.T. 289 ;</i> ἐπ' ἀγκάλαις λαϐεῖν, EUR. <i>Ion 761 ; rar. au sg</i>. φέρειν ἐν τῇ ἀγκάλῃ, HDT. <i>6, 61, m. sign. ;</i><br><b> 2</b> toute chose arrondie <i>ou</i> recourbée qui enveloppe <i>ou</i> enserre : πετραία ἀγκ. ESCHL. <i>Pr. 1019,</i> l’embrassement <i>ou</i> l’étreinte d’un rocher ; πόντιαι ἀγκ. ESCHL. <i>Ch. 586,</i> les bras de la mer ; ὑγραῖς ἐν ἀγκ. EUR. <i>fr. 935 Nauck,</i> dans ses bras humides, <i>en parl. de l’air</i>.<p><b>Étym</b>. <i>cf</i>. ἀγκάς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγκαλη - ἀγκάλη</font>\n<br><br>Vient de agkos (un pli)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK2.28\">Luc 2.28</a></li>\n</ul>\n</td></tr>\n</table>","G44":"<h1>agkistron</h1>\n<p>Strong n° 44 <i>Prononciation [ang'-kis-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un hameçon, un petit crochet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγκιστρον</b> <b>ου (τὸ)</b> crochet :<br><b> 1</b> crochet d’hameçon, hameçon, OD. <i>4, 369 ;</i> HDT. <i>2, 70, etc. ;</i><br><b> 2</b> crochet de fuseau, PLAT. <i>Rsp. 616</i> c.<p><b>➼</b> <i>Avec crase : sg. gén. dor</i>. τὠγκίστρω, THCR. <i>Idyl. 21, 56 ; dat</i>. τὠγκίστρῳ, THCR. <i>Idyl. 21, 46 ; plur</i>. τἄγκιστρα, THCR. <i>Idyl. 21, 10</i>.</p><p><b>Étym</b>. ἄγκος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγκιστρον - ἄγκιστρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT17.27\">Matthieu 17.27</a></li>\n</ul>\n</td></tr>\n</table>","G45":"<h1>agkura</h1>\n<p>Strong n° 45 <i>Prononciation [ang'-koo-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une ancre</li>\n<li>métaph. sauvegarder</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγκυρα</b> <b>ας (ἡ)</b> <font color=\"brown\">[ῡ]</font> :<br><b> 1</b> ancre : ἄγκυραν καθιέναι, HDT. <i>7, 36 ;</i> μεθιέναι, ESCHL. <i>Ch. 662 ;</i> ἀφιέναι, XÉN. <i>An. 3, 5, 10,</i> jeter l’ancre ; ἄγκυραν αἴρειν, αἴρεσθαι, PLUT. <i>Pomp. 50, 80,</i> ἀναιρεῖσθαι, ANTH. <i>10, 1,</i> lever l’ancre ; ἐπ' ἀγκύρας ὁρμεῖσθαι, HDT. <i>7, 188, ou</i> ἀποσαλεύειν, DÉM. <i>1213, 24,</i> être dans le port, à l’ancre ; <i>prov</i>. <font color=\"blue\">ἐπὶ δυοῖν ἀγκύραιν ὁρμεῖν</font>, DÉM. <i>1295 fin,</i> être mouillé sur deux ancres, <i>càd</i>. avoir pris ses précautions et se croire en sûreté ; ἄγκυρα ἱερά, PLUT. <i>M. 815</i> d, ancre sacrée, ancre de miséricorde, dernière chance de salut ; <i>fig</i>. soutien, appui, espérance, SOPH. <i>fr. 612 ;</i> EUR. <i>Hel. 277, Hec. 80, etc. ;</i><br><b> 2</b> croc de laboureur, TH. <i>C.P. 3, 2, 2 ;</i><br><b> 3</b> <i>c</i>. αἰδοῖον, EPICH.<p><b>➼</b> <i>Ion</i>. ἀγκύρη, THGN. <i>459 ;</i> HDT. <i>ll. cc</i>.</p><p><b>Étym</b>. <i>cf. p.-ê</i>. ἀγκών, <i>mais suff. pré-grec</i> -υρα, <i>cf</i>. γέφυρα, γόργυρα ; <i>lat</i>. ancora <i>y est emprunté</i>.</p> <p><font color=\"purple\">Syn.</font></b></i> εὐναία.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγκυρα - ἄγκυρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3) => <a class=\"ref\" data-r=\"ACT27.29,30,40\">Actes 27.29, 30, 40</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB6.19\">Hébreux 6.19</a></li>\n</ul>\n</td></tr>\n</table>","G46":"<h1>agnaphos</h1>\n<p>Strong n° 46 <i>Prononciation [ag'-naf-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nouveau, non porté, non usé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγναφος</b> <b>ἄ·γναφος, ος, ον</b> <font color=\"brown\">[ᾰφ]</font> <i>c</i>. ἄγναπτος, NT. <i>Matth. 9, 16 ; Marc. 2, 21<p>➪ <font color=\"red\">ἄ·γναπτος,</font> ος, ον,</b> non foulé, non cardé, <i>d'où :</i> <br><b>1</b> qui est encore neuf, P<small>LUT</small>. <i>M. 691</i> d <br><b>2</b> non nettoyé, non purifié, P<small>LUT</small>. <i>M. 169</i> c </p><p><i><b><font color=\"brown\">Étym.</font></b> : </i>ἀ, γνάπτω.</p></i>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-γναφος - ἄγναφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT9.19\">Matthieu 9.19</a></li>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK2.21\">Marc 2.21</a></li>\n</ul>\n</td></tr>\n</table>","G47":"<h1>hagneia</h1>\n<p>Strong n° 47 <i>Prononciation [hag-ni'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pureté, vie sans péché</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγνεία</b> <b>ας (ἡ) :<br> 1</b> pureté, chasteté, SOPH. <i>O.R. 864 ;</i> ANTH. <i>App. 99, etc. ; d’où</i> état d’une âme pure, PLAT. <i>Leg. 909</i> e ;<br><b> 2</b> purification, Ps.-PHOCYL. <i>228 ;</i> ISOCR. <i>225</i> d, <i>etc</i>.<p><b>Étym</b>. ἁγνεύω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνεια - ἁγνεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (2) => <a class=\"ref\" data-r=\"1TI4.12;5.2\">1 Timothée 4.12 ; 5.2</a></li>\n</ul>\n</td></tr>\n</table>","G48":"<h1>hagnizo</h1>\n<p>Strong n° 48 <i>Prononciation [hag-nid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cérémonial : rendre pur, purifier, nettoyer</li>\n<li>moralement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγνίζω</b> <font color=\"darkgreen\">(<i>ao</i>. ἥγνισα, <i>ao. pass</i>. ἡγνίσθην)</font><br><b> 1</b> purifier par l’eau (<i>p. opp. à</i> καθαίρειν, purifier par le feu, PLUT. <i>M. 263</i> e), nettoyer, laver, SOPH. <i>Aj. 655 ;</i> χέρας ἁγνίζειν μιάσματος, EUR. <i>H.f. 1324,</i> purifier <i>ou</i> laver ses mains d’une souillure ;<br><b> 2</b> purifier par le feu, EUR. <i>Suppl. 1211 ; p. ext</i>. brûler, détruire, SOPH. <i>fr. 119 ;</i><br><b> 3</b> purifier, <i>en gén. ;</i> purifier (un mort) suivant les rites, <i>acc</i>. SOPH. <i>Ant. 545 ;</i><br><b> 4</b> <i>p. suite,</i> garder ses lèvres <i>ou</i> ses mains pures, <i>d’où au pass</i>. s’abstenir de, <i>avec</i> ἀπό <i>et le gén</i>. SPT. <i>Num. 6, 3</i>.<p><b>Étym</b>. ἁγνός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνιζω - ἁγνίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Jean (1) => <a class=\"ref\" data-r=\"JHN11.55\">Jean 11.55</a></li>\n<li>Actes (3) => <a class=\"ref\" data-r=\"ACT21.24,26;24.18\">Actes 21.24,26 ; 24.18</a></li>\n<li>Jacques (1) => <a class=\"ref\" data-r=\"JAS4.8\">Jacques 4.8</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE1.22\">1 Pierre 1.22</a></li>\n<li>1 Jean (1) => <a class=\"ref\" data-r=\"1JN3.3\">1 Jean 3.3</a></li>\n</ul>\n</td></tr>\n</table>","G49":"<h1>hagnismos</h1>\n<p>Strong n° 49 <i>Prononciation [hag-nis-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>purification, expiation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγνισμός</b> <b>οῦ (ὁ)</b> purification, DH. <i>3, 22 ;</i> SPT. <i>Num. 6, 3</i>. abstinence ; purification rituelle, expiation.<p><b>Étym</b>. ἁγνίζω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνισμος - ἁγνισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT21.26\">Actes 21.26</a></li>\n</ul>\n</td></tr>\n</table>","G50":"<h1>agnoeo</h1>\n<p>Strong n° 50 <i>Prononciation [ag-no-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être ignorant, ne pas connaître</li>\n<li>ne pas comprendre, inconnu</li>\n<li>errer ou pécher à travers l'erreur, avoir tort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγνοέω</b> <b>ἀγνοέω-οῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ἠγνόουν, <i>f</i>. ἀγνοήσω, <i>ao</i>. ἠγνόησα ; <i>pass. ao</i>. ἠγνοήθην, <i>pf</i>. ἠγνόημαι)</font><br><b> 1</b> ne pas connaître, ignorer, <i>abs. ou avec l’acc</i>. HDT. <i>4, 156 ; etc</i>. ATT. ; περί τινος, PLAT. <i>Phædr. 277</i> d, être ignorant de qqe ch. ; <i>avec un gén. de pers. et un acc. de chose :</i> ἀγνοοῦντες ἀλλήλων ὅ τι λέγομεν, PLAT. <i>Gorg. 517</i> c, ignorant ce que nous disons mutuellement ; <i>avec une prop. inf</i>. SPT. <i>Sap. 7, 12 ; avec une prop. au part. :</i> τίς ἀγνοεῖ τὸν ἐκεῖθεν πόλεμον δεῦρο ἥξοντα ; DÉM. <i>13, 17,</i> qui ne sait que la guerre partie de là viendra jusqu’ici ? <i>avec une conj</i>. ὅτι, ὡς, DÉM. <i>565, 8, etc. ;</i> εἰ, XÉN. <i>An. 6, 5, 12 ;</i> οὐκ ἀγνοῶ, IL. <i>1, 537 ; 2, 807 ; 13, 28 ;</i> ATT. je n’ignore pas, je sais fort bien ; <i>pass</i>. ἀγνοοῦμαι, ATT. on ne sait pas que je, <i>etc. ; avec une conj</i>. ἠγνοῆσθαι ξύμπασιν ὅτι, PLAT. <i>Leg. 797</i> a, tout le monde ignore que, <i>etc. ;</i><br><b> 2</b> ne pas reconnaître : τινα, OD. <i>20, 15 ; 23, 95 ; 24, 218,</i> qqn ;<br><b> 3</b> se tromper, être dans l’erreur, ANT. <i>134, 30 ;</i> ISOCR. <i>167</i> c ; <i>au sens mor</i>. être en faute sans le savoir, faire le mal par ignorance, PLUT. <i>M. 533</i> c ; SPT. <i>Lev. 4, 13 ; 5, 18 ; Num. 12, 11, etc. ;</i> NT. <i>Hebr. 5, 2</i>.<p><b>➼</b> <i>Prés. sbj. 3 sg. épq</i>. ἀγνοιῇσι, OD. <i>24, 218 ; part. ion. pl</i>. ἀγνοεῦντες, HDT. <i>4, 156. Impf. ion</i>. ἠγνόεον, HPC. <i>2, 226 Littré. Ao. épq. et poét</i>. ἠγνοίησα, IL. <i>2, 807 ;</i> HÉS. <i>Th. 551 ;</i> ANTH. <i>9, 548 ; part. fém</i>. ἀγνοιήσασ', OD. <i>20, 15. Ao. itér. 3 sg</i>. ἀγνώσασκε, OD. <i>23, 95. Moy. fut. au sens pass</i>. ἀγνοήσομαι, DÉM. <i>310, 7 ;</i> LUC. <i>J. tr. 5</i>.</p><p><b>Étym</b>. ἀ. <i>th</i>. γνοϝο-, γνω-; <i>cf</i>. γιγνώσκω.<br><font color=\"red\">Ant.</font></b></i> γιγνώσκω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνοεω - ἀγνοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 11 livres bibliques (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK9.32\">Marc 9.32</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK9.45\">Luc 9.45</a></li>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT13.27;17.23\">Actes 13.27 ; 17.23</a></li>\n<li>Romains (6) => <a class=\"ref\" data-r=\"ROM1.13;2.4;6.3;;7.1;10.3;11.25\">Romains 1.13 ; 2.4 ; 6.3 ; 7.1 ; 10.3 ; 11.25</a></li>\n<li>1 Corinthiens (4) => <a class=\"ref\" data-r=\"1CO10.1;12.1;14.38\">1 Corinthiens 10.1 ; 12.1 ; 14.38</a></li>\n<li>2 Corinthiens (3) => <a class=\"ref\" data-r=\"2CO1.8;2.11;6.9\">2 Corinthiens 1.8 ; 2.11 ; 6.9</a></li>\n<li>Galates (1) => <a class=\"ref\" data-r=\"GAL1.22\">Galates 1.22</a></li>\n<li>1 Thessaloniciens (1) => <a class=\"ref\" data-r=\"1TH4.13\">1 Thessaloniciens 4.13</a></li>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI1.13\">1 Timothée 1.13</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB5.2\">Hébreux 5.2</a></li>\n<li>2 Pierre (1) => <a class=\"ref\" data-r=\"2PE2.12\">2 Pierre 2.12</a></li>\n</ul>\n</td></tr>\n</table>","G51":"<h1>agnoema</h1>\n<p>Strong n° 51 <i>Prononciation [ag-no'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un péché commis dans l'ignorance ou l'insouciance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγνόημα</b> <b>ατος (τὸ) :<br> 1</b> ignorance, SPT. <i>Sir. 51, 19 ;</i><br><b> 2</b> faute par ignorance, erreur, TH. <i>H.P. 9, 4, 8 ;</i> SPT. <i>Tob. 3, 3 ; Judith 5, 20 ;</i> NT. <i>Hebr. 9, 7</i>.<p><b>Étym</b>. ἀγνοέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνοημα - ἀγνόημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB9.7\">Hébreux 9.7</a></li>\n</ul>\n</td></tr>\n</table>","G52":"<h1>agnoia</h1>\n<p>Strong n° 52 <i>Prononciation [ag'-noy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manque de connaissance, ignorance\n<ol type=\"a\">\n<li>spécialement des choses divines</li>\n<li>aveuglement moral</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγνοια</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰ <i>fin</i>.]</font> :<br><b> 1</b> ignorance, THC. <i>8, 92 ;</i> XÉN. <i>Cyr. 3, 1, 38 ;</i> SOPH. <i>Tr. 419, etc. ;</i> θεραπεύειν ἀγνοίᾳ, THC. <i>2, 47,</i> soigner une maladie sans la connaître ;<br><b> 2</b> faute par ignorance, <font color=\"darkblue\">SEPT</font> péché. <i>Gen. 26, 10 ; Lev. 5, 18, etc. ;</i> PHIL. <i>1, 345 ;</i><br><b> 3</b> inadvertance, méprise, erreur, DÉM. <i>271, 15 ; 1472, 5</i>.<p><b>➼</b> <i>Anc. att</i>. ἀγνοία <font color=\"brown\">[ᾱ <i>fin</i>.]</font> SOPH. <i>Tr. 350, Ph. 124</i>.</p> <br><i><b><font color=\"darkblue\">Étym.</font></b></i> ἀγνοέω.<br><i><b><font color=\"red\">Ant.</font></b></i> ἐπιστήμη, σύνεσις.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνοια - ἄγνοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT3.17;17.30\">Actes 3.17 ; 17.30</a></li>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH4.18\">Éphésiens 4.18</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE1.14\">1 Pierre 1.14</a></li>\n</ul>\n</td></tr>\n</table>","G53":"<h1>hagnos</h1>\n<p>Strong n° 53 <i>Prononciation [hag-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>digne de révérence, vénérable, sacré</li>\n<li>pur\n<ol type=\"a\">\n<li>pur charnellement, chaste, modeste</li>\n<li>pur de toute faute, immaculé</li>\n<li>propre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγνός</b> <b>ή, όν :<br>   I</b> <i>intr. :</i><br><b> 1</b> pur, saint, sacré, <i>en parl. des choses divines (éther,</i> ESCHL. <i>Pr. 281 ; lumière,</i> SOPH. <i>El. 86 ; oracle,</i> EUR. <i>Ion 243, etc.) ; des lieux ou objets consacrés aux dieux (bois sacré,</i> HH. <i>Merc. 187 ; temple,</i> PD. <i>P. 4, 204 ; sacrifices,</i> SOPH. <i>Tr. 287, etc</i>.) ;<br><b> 2</b> <i>en part. des dieux eux-mêmes,</i> pur, chaste (<i>Artémis,</i> OD. <i>5, 123 ; 18, 202, etc. ; Dèmèter,</i> HH. <i>Cer. 203, etc. ; qqf. Zeus,</i> ESCHL. <i>Suppl. 652 ; Apollon,</i> PD. <i>P. 9, 112) ; postér. en parl. des hommes,</i> ESCHL. <i>Ag. 244, etc. ; particul. d’Hippolyte,</i> EUR. <i>Hipp. 102 ;</i><br><b> 3</b> pur, exempt de souillure, <i>en gén.,</i> SOPH. <i>Ant. 889, etc. ;</i> EUR. <i>Or. 1604, etc. ; avec un rég</i>. ἁ. αἵματος, EUR. <i>Hipp. 316 ;</i> φόνου, PLAT. <i>Leg. 759</i> c, pur de sang, de meurtre ; ἁ. ἀπό τινος, DÉM. <i>59, 78 Baiter-Sauppe,</i> pur de qqe souillure : <i>abs. en parl. d’animaux :</i> βοὸς ἁγνῆς, ESCHL. <i>Pers. 611,</i> génisse dont le cou est vierge, <i>càd</i>. n’a jamais été souillé par le joug ; <i>p. ext</i>. qui s’abstient de, <i>gén</i>. EUR. <i>Hipp. 138</i>.<br><i>● Cp</i>. ἁγνότερος, XÉN. <i>Conv. 8, 9 ;</i> <i>● Sup</i>. -ότατος, PD. <i>P. 1, 41</i>.<p><b>➼</b> <font color=\"brown\">[ᾰγ]</font> NAZ. <i>2, 31, 37, 39, etc</i>.</p><br><font color=\"darkblue\">SEPT</font> innocent.<p><b>Étym</b>. <i>R. indo-europ</i>. *(H)ih<sub>2</sub>ǵ-no-, pur, sacré, <i>cf</i>. ἅγιος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνος - ἁγνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (2) => <a class=\"ref\" data-r=\"2CO7.11;11.2\">2 Corinthiens 7.11 ; 11.2</a></li>\n<li>Philippiens (1) => <a class=\"ref\" data-r=\"PHP4.8\">Philippiens 4.8</a></li>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI5.22\">1 Timothée 5.22</a></li>\n<li>Tite (1) => <a class=\"ref\" data-r=\"TIT2.5\">Tite 2.5</a></li>\n<li>Jacques (1) => <a class=\"ref\" data-r=\"JAS3.17\">Jacques 3.17</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE3.2\">1 Pierre 3.2</a></li>\n<li>1 Jean (1) => <a class=\"ref\" data-r=\"1JN3.3\">1 Jean 3.3</a></li>\n</ul>\n</td></tr>\n</table>","G54":"<h1>hagnotes</h1>\n<p>Strong n° 54 <i>Prononciation [hag-not'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pureté, chasteté, vie droite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁγνότης</b> <b>ητος (ἡ)</b> pureté, chasteté, NT. <i>2Cor. 6, 6</i>.<p><b>Étym</b>. ἁγνός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνοτης - ἁγνότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1) => <a class=\"ref\" data-r=\"2CO6.6\">2 Corinthiens 6.6</a></li>\n</ul>\n</td></tr>\n</table>","G55":"<h1>hagnos</h1>\n<p>Strong n° 55 <i>Prononciation [hag-noce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>chaste, propre, pur, avec sincérité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγνώς</b> <b>ἀ·γνώς, ῶτος (ὁ, ἡ) :<br>   I</b> <i>pass. :</i><br><b> 1</b> inconnu, ESCHL. <i>Ch. 677 ;</i> SOPH. <i>Ph. 1008 ;</i> ἀ. τινι, OD. <i>5, 79,</i> inconnu de qqn ;<br><b> 2</b> qui agit à l’insu de, <i>dat</i>. THC. <i>1, 137 ;</i> EUR. <i>Ion 14 ;</i><br><b> 3</b> qu’on ne peut reconnaître, inintelligible, obscur, ESCHL. <i>Ag. 1051 ;</i> SOPH. <i>Ant. 1001 ;</i><br><b>   II</b> <i>act. :</i><br><b> 1</b> qui ne sait pas, ignorant : σοῦ τυχὼν ἀγνῶτος, SOPH. <i>O.R. 677,</i> t’ayant rencontré me méconnaissant, méconnu de toi ; ἀγνώς τινος, THC. <i>3, 53 ;</i> ARSTT. <i>Soph. el. 22, 4,</i> qui ne connaît pas qqn <i>ou</i> qqe ch. ; <i>avec un rel</i>. ἀγνὼς τί δύναται, XÉN. <i>Œc. 20, 13,</i> ignorant ce que peut (produire la terre) ;<br><b> 2</b> <i>particul</i>. qui ne reconnaît pas (qqn) SOPH. <i>O.R. 1133</i>.<br><i>● Sup</i>. ἀγνώστατος (<i>v</i>. ἄγνωστος).<br><font color=\"darkblue\">SEPT</font> chastement , avec des intentions pures.<p><b>Étym</b>. ἀ, γιγνώσκω.<b>ἁγνῶς</b> <i>adv</i>. purement, saintement, HH. <i>Ap. 121 ;</i> HÉS. <i>O. 339 ;</i> XÉN. <i>Mem. 3, 8, 10</i>.</p><p><b>Étym</b>. ἁγνός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγνως - ἁγνῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1) => <a class=\"ref\" data-r=\"PHP1.17\">Philippiens 1.17</a></li>\n</ul>\n</td></tr>\n</table>","G56":"<h1>agnosia</h1>\n<p>Strong n° 56 <i>Prononciation [ag-no-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>méconnaissance, ignorance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγνωσία</b> <b>ας (ἡ) :<br> 1</b> ignorance de, <i>gén</i>. THC. <i>8, 66 ;</i> EUR. <i>Med. 1204 ; abs</i>. ignorance, <i>p. opp. à</i> γνῶσις, PLAT. <i>Soph. 267</i> b ;<br><b> 2</b> obscurité, PLAT. <i>Menex. 238</i> d.<br><b>3</b> <font color=\"darkblue\">SEPT</font> manque de perception spirituelle , méconnaissance , discours ignorant.<br><i><b><font color=\"darkblue\">Étym.</font></b></i> ἀγνώς.<br><i><b><font color=\"red\">Ant.</font></b></i> γνῶσις.<br><i><b><font color=\"darkorange\">Par.</font></b></i> ὑπεροψία.<br><i><b><font color=\"purple\">Syn.</font></b></i> ἀπορία.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-γνωσια - ἀγνωσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO14.34\">1 Corinthiens 15.34</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE2.15\">1 Pierre 2.15</a></li>\n</ul>\n</td></tr>\n</table>","G57":"<h1>agnostos</h1>\n<p>Strong n° 57 <i>Prononciation [ag'-noce-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inconnu, oublié</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγνωστος</b> <b>ἄ·γνωστος, ος, ον :<br>   I</b> <i>pass. :</i><br><b> 1</b> inconnu, ignoré, EUR. <i>I.T. 94 ;</i> ἄ. τινι, OD. <i>2, 175,</i> inconnu de qqn ; <i>subst</i>. ὁ Ἄγνωστος, LUC. <i>Philopatr. 9 ;</i> NT. <i>Ap. 17, 23,</i> le Dieu inconnu, <i>à Athènes ;</i><br><b> 2</b> qu’on ne peut connaître, inintelligible, OD. <i>13, 191 ;</i> THC. <i>3, 94 ; ou</i> qui échappe à la connaissance, PLAT. <i>Theæt. 202</i> b, <i>etc. ;</i><br><b>   II</b> <i>act</i>. qui ne sait pas, ignorant de, <i>gén</i>. PD. <i>O. 6, 67 ; abs</i>. ignorant, LUC. <i>Halc. 3</i>.<br><i>● Cp</i>. -ότερος, ARSTT. <i>An. pr. 2, 16 ; Metaph. 1, 3, etc.</i> <i>● Sup</i>. -ότατος, THC. <i>3, 94 (var</i>. ἀγνώστατος).<p><b>Étym</b>. ἀ, γνωστός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-γνωστος - ἄγνωστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT17.23\">Actes 17.23</a></li>\n</ul>\n</td></tr>\n</table>","G58":"<h1>agora</h1>\n<p>Strong n° 58 <i>Prononciation [ag-or-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>n'importe quelle assemblée, spécialement du peuple</li>\n<li>le lieu de l'assemblée\n<ol type=\"a\">\n<li>pour les débats publics</li>\n<li>pour les élections</li>\n<li>pour les procès</li>\n<li>pour acheter et vendre (marchés)</li>\n<li>pour toute sorte d'affaires</li>\n</ol>\n</li>\n<li>place de marché, rue</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγορά</b> <b>ᾶς (ἡ)</b> <font color=\"brown\">[ᾰᾱ]</font> :<br><b>   I</b> assemblée, <i>particul. :</i><br><b> 1</b> <i>dans</i> HOM. assemblée du peuple (<i>p. opp. à</i> βουλή, le Conseil des chefs) IL. <i>2, 51, 93, etc. ;</i> OD. <i>2, 26, etc. ;</i> ἀγορὴν ποιεῖσθαι, IL. <i>8, 2,</i> tenir une assemblée ; ἀγορήνδε καλέσσασθαι, IL. <i>1, 54 ; ou</i> κηρύσσειν, IL. <i>2, 51,</i> appeler à l’assemblée ; ἀγορὴν λύειν, IL. <i>1, 305 ;</i> OD. <i>2, 69,</i> dissoudre l’assemblée ;<br><b> 2</b> <i>à Athènes,</i> assemblée des dèmes et des tribus (<i>p. opp. à</i> ἐκκλησία, l’assemblée du peuple) ; ἀγορὰν ποιεῖν, ESCHN. <i>57, 37,</i> tenir une assemblée ;<br><b> 3</b> ἀγοραὶ Πυλάτιδες, SOPH. <i>Tr. 638,</i> le Conseil des Amphictions, <i>aux Thermopyles ;</i><br><b> 4</b> assemblée <i>en gén. :</i> στρατιωτῶν ἀγορὰν συνάγειν <i>ou</i> συλλέγειν, XÉN. <i>An. 5, 7, 3,</i> réunir les soldats en assemblée ; <i>postér. à Rome,</i> ἀγ. δικῶν, LUC. <i>Bis acc. 4 et 12,</i> assemblée judiciaire ; <i>en parl. d’animaux :</i> μυρμήκων ἀγ. LUC. <i>Ic. 19,</i> assemblée de fourmis ; <i>cf</i>. PHILSTR. <i>Her. 4 ;</i><br><b>   II</b> discours devant une assemblée, harangue : ἀγορὰς ἀγορεύειν, IL. <i>2, 788,</i> tenir des discours ; εἰδὼς ἀγορέων, IL. <i>9, 441,</i> habile à parler en public ;<br><b>   III</b> lieu où l’on se réunit, <i>d’où :</i><br><b> 1</b> place publique, IL. <i>7, 382 ; 11, 807 ;</i> OD. <i>6, 266 ; particul. à Athènes,</i> agora, <i>non « place publique » au sens moderne du mot, mais vaste emplacement, formant comme une petite ville dans la grande, planté d’allées de platanes et de peupliers, avec des constructions (palais du sénat, tribunaux, temples, etc.), divisé en quartiers assignés à chaque corporation de marchands, et où ceux-ci s’établissaient soit en plein vent, soit dans des baraques ;</i> ἐν τῇ ἀγορᾷ, XÉN. <i>Œc. 7, 1,</i> sur la place publique ; ἐν ἀγορᾷ πληθούσῃ, PLAT. <i>Gorg. 469</i> d, à l’heure où la place est remplie de monde (de 10 h à 13 h) ; ἀγορᾶς πληθούσης, XÉN. <i>Mem. 1, 1, 10 ;</i> ἀγορῆς πληθυούσης, HDT. <i>4, 181, m. sign. ;</i> περὶ <i>ou</i> ἀμφὶ ἀγορὰν πλήθουσαν, XÉN. <i>An. 2, 1, 7, etc</i>. vers l’heure où la place est remplie ; ἀγορῆς πληθώρη, HDT. <i>2, 173, etc</i>. l’heure où la place est remplie, <i>p. opp. à</i> ἀγορῆς διάλυσις, HDT. <i>3, 104,</i> l’heure où l’assemblée est dissoute ; πονηρὸς κἀξ ἀγορᾶς, AR. <i>Eq. 181,</i> mauvais drôle et vagabond ;<br><b> 2</b> place où siège un tribunal, IL. <i>16, 387 (cf</i>. OD. <i>12, 439</i>) ;<br><b> 3</b> lieu de réunion pour les marchands, marché, <i>d’où</i> emplacement du marché, HOM. <i>Ep. 14, 5 ;</i> ATT. ; ἀγορὰν ποιεῖσθαι, THC. <i>1, 62,</i> établir un marché pour y acheter soi-même, <i>càd</i>. en y attirant des vendeurs à qui l’on achètera ; ἐξ ἀγορᾶς ὠνεῖσθαι, ATT. <i>ou</i> πρίασθαι, XÉN. <i>Œc. 8, 22,</i> rapporter ses emplettes du marché, acheter au marché ; οἱ ἐκ τῆς ἀγορᾶς, XÉN. <i>An. 1, 2, 18,</i> les gens du marché, les marchands ;<br><b> 4</b> marchandises, denrées du marché ; ἀγορὰν παρέχειν, THC. <i>6, 50, ou</i> παρασκευάζειν, THC. <i>7, 40 ;</i> XÉN. <i>Hell. 3, 4, 11,</i> fournir des provisions ; ἄγειν, φέρειν, κομίζειν, XÉN. <i>Cyr. 2, 4, 32 ; An. 5, 5, 19 ; Cyr. 6, 2, 11,</i> amener <i>ou</i> apporter des denrées ; ἀγορὰ φιλάνθρωπος, PLUT. <i>Cor. 16,</i> vivres à bon marché ; <i>p. ext</i>. vivres, <i>en gén.,</i> provisions : σῖτον, οἶνον, καὶ τὴν ἄλλην ἀγοράν, ARSTT. <i>Œc. 2, 8,</i> le blé, le vin et les autres provisions ; ἀγορᾶς ἐπιλιπούσης, PLUT. <i>Syll. 4,</i> les vivres étant venus à manquer ; ἀγορὰν περικόπτειν, DH. <i>10, 43,</i> couper les vivres ;<br><b> 5</b> vente publique : ἀγορὰν προκηρύττειν, EL. <i>V.H. 4, 1,</i> annoncer une vente publique.<p><b>Étym</b>. ἀγείρω.<b>Ἀγορά</b> <b>ᾶς (ἡ) :<br> 1</b> Agora, <i>v. de la Chersonèse de Thrace,</i> DÉM. <i>7, 39 Baiter-Sauppe ;</i><br><b> 2</b> Κεραμῶν Ἀγορά, XÉN. <i>An. 1, 2, 10, litt</i>. « le Marché des potiers » <i>v. de Mysie</i>.</p><p><b>➼</b> <i>Ion</i>. -ή, HDT. <i>7, 58</i>.</p><p><font color=\"red\">Ant.</font></b></i> βουλή.<br><i><b><font color=\"darkorange\">Par.</font></b></i> πρητήριον, ἐκκλησία.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγορα - ἀγορά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3) => <a class=\"ref\" data-r=\"MAT11.16;20.3;23.7\">Matthieu 11.16 ; 20.3 ; 23.7</a></li>\n<li>Marc (3) => <a class=\"ref\" data-r=\"MRK6.56;7.4;12.38\">Marc 6.56  7.4 ; 12.38</a></li>\n<li>Luc (3) => <a class=\"ref\" data-r=\"LUK7.32;11.43;20.46\">Luc 7.32 ; 11.43 ; 20.46</a></li>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT16.19;17.17\">Actes 16.19 ; 17.17</a></li>\n</ul>\n</td></tr>\n</table>","G59":"<h1>agorazo</h1>\n<p>Strong n° 59 <i>Prononciation [ag-or-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être sur une place de marché, s'y activer</li>\n<li>y faire des affaires, acheter ou vendre</li>\n<li>pour les désœuvrés : hanter cette place, y flâner</li>\n<li>acheter des personnes des esclaves</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγοράζω</b> <font color=\"brown\">[ᾰγ]</font> :<br><b>   I</b> être <i>ou</i> aller sur la place publique, <i>d’où :</i><br><b> 1</b> camper sur la place publique, THC. <i>6, 51 ;</i><br><b> 2</b> flâner sur la place publique, <i>d’où</i> être flâneur, paresseux, COR. <i>et</i> PD. (SCH.-AR. <i>Ach. 720</i>) ;<br><b> 3</b> prendre part aux affaires et aux discussions de la place publique, AR. <i>Eq. 1373 ;</i><br><b> 4</b> aller au marché, HDT. <i>2, 35, etc. ; d’où</i> acheter au marché, acheter, AR. <i>Ach. 625, etc. ;</i> XÉN. <i>An. 1, 5, 10 ;</i><br><b><i>Moy</i></b>. acheter pour soi-même, faire ses provisions, XÉN. <i>An. 1, 3, 14 ;</i> DÉM. <i>1215, 2</i>.<p><b>➼</b> <font color=\"brown\">[ᾰγ]</font> COM. ANON. (<i>Com. fr. 4, 7, 620). Prés. dor</i>. ἀγοράσδω, THCR. <i>Idyl. 15, 16. Fut. mégar</i>. ἀγορασῶ <font color=\"brown\">[ᾰᾰ]</font> <i>d’où part</i>. ἀγορασοῦντες, AR. <i>Ach. 750. Inf. pf. pass</i>. ἠγοράσθαι, <i>au sens moy</i>. DÉM. <i>929, 6</i>.</p><p><b>Étym</b>. ἀγορά.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγοραζω - ἀγοράζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 30 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (7) => <a class=\"ref\" data-r=\"MAT13.44,46;14.15;21.12;25.9,10;27.7\">Matthieu 13.44,46 ; 14.15 ; 21.12  ; 25.9,10 ; 27.7</a></li>\n<li>Marc (5) => <a class=\"ref\" data-r=\"MRK6.36,37;11.15;15.46;16.1\">Marc 6.36,37 ; 11.15 ; 15.46 ; 16.1</a></li>\n<li>Luc (5) => <a class=\"ref\" data-r=\"LUK9.13;14.18,19;17.28;22.36\">Luc 9.13 ; 14.18,19 ; 17.28 ; 22.36</a></li>\n<li>Jean (3) => <a class=\"ref\" data-r=\"JHN4.8;6.5;13.29\">Jean 4.8 ; 6.5 ; 13.29</a></li>\n<li>1 Corinthiens (3) => <a class=\"ref\" data-r=\"1CO6.20;7.23;7.30\">1 Corinthiens 6.20 ; 7.23 ; 7.30</a></li>\n<li>2 Pierre (1) => <a class=\"ref\" data-r=\"2PE2.1\">2 Pierre 2.1</a></li>\n<li>Apocalypse (6) => <a class=\"ref\" data-r=\"REV3.18;5.9;13.17;14.3,4;18.11\">Apocalypse 3.18 ; 5.9 ; 13.17 ; 14.3,4 ; 18.11</a></li>\n</ul>\n</td></tr>\n</table>","G60":"<h1>agoraios</h1>\n<p>Strong n° 60 <i>Prononciation [ag-or-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sur ou aux environs de la place publique, la place de marché</li>\n<li>ceux qui fréquentent cette place\n<ol type=\"a\">\n<li>trafiquants insignifiants, marchands au détail</li>\n<li>désœuvrés, flâneurs, le peuple commun, la populace, vaurien, mauvais sujet</li>\n</ol>\n</li>\n<li>généralement, propre à l'assemblée, procès judiciaire, transactions, jour d'audience</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγοραῖος</b> <b>ος, ον</b> <font color=\"brown\">[ᾰ]</font> de place publique <i>ou</i> de marché, <i>d’où :</i><br><b> 1</b> dont les images se dressent sur la place publique, <i>épith. de certains dieux (Zeus, protecteur des assemblées,</i> HDT. <i>5, 46 ;</i> ESCHL. <i>Eum. 973 ; Hermès, protecteur des marchands,</i> AR. <i>Eq. 297, etc. ; Athèna, Artémis,</i> PAUS. <i>5, 14, 4 ; 3, 11, 9</i>) ;<br><b> 2</b> qui passe son temps sur la place publique, <i>d’où</i> oisif, vagabond, <i>à côté de</i> κακός, AR. <i>Eq. 214 ; joint à</i> πανοῦργος, AR. <i>Ran. 1015 ; à</i> φαῦλοι, PLAT. <i>Prot. 347</i> e ;<br><b> 3</b> qui fréquente les marchés (acheteur <i>ou</i> marchand) XÉN. <i>Hell. 6, 2, 23 ;</i> ARSTT. <i>Pol. 4, 3, 2, etc. ;</i> οἱ ἀγοραῖοι, les petits marchands, HDT. <i>1, 93 ; p. opp. à</i> ἔμποροι, XÉN. <i>Vect. 3, 13 ;</i> ἀγ. ἄνθρωποι, PLAT. <i>Prot. 347</i> c ; AR. <i>Ran. 1015,</i> habitués du marché, <i>d’où</i> gens du commun ; <i>p. suite, en parl. de choses,</i> commun, trivial, grossier, AR. <i>Pax 750 ;</i> ARSTT. <i>Nic. 8, 13, 6 ;</i><br><b> 4</b> qui concerne les marchés : ἀγοραῖα τέλη, ARSTT. <i>Œc. 2, 1, 4,</i> droits perçus sur les marchés ; τὸ ἀγοραῖον, ARSTT. <i>Pol. 4, 3,</i> le quartier des marchés ; τὰ ἀγοραῖα, PLAT. <i>Rsp. 425</i> c, les affaires qui se traitent au marché (achats et ventes) ;<br><b> 5</b> qui concerne les affaires publiques <i>ou</i> judiciaires : ἀνὴρ ἀγ. homme propre aux discussions de l’agora, <i>càd</i>. orateur politique, PLUT. <i>Per. 11 ; ou</i> avocat, PLUT. <i>de Vit. pud. 8 ;</i> ἀγοραῖοι (<i>s.-e</i>. ἡμέραι) STR. <i>629 ;</i> NT. <i>Ap. 19, 38,</i> jours où siègent les tribunaux, jours de barreau.<br><i>● Cp</i>. -ότερος, PTOL. (ATH. <i>438</i> f).<p><b>➼</b> <i>Fém</i>. -αία, PAUS. <i>ll. cc</i>.</p><p><b>Étym</b>. ἀγορά.<br><font color=\"red\">Ant. 3</font></b></i> κάπηλοι, ἔμποροι.<br><i><b><font color=\"darkorange\">Par.</font></b></i> κόβαλος, πανοῦργος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγοραιος - ἀγοραῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT17.5;19.38\">Actes 17.5 ; 19.38</a></li>\n</ul>\n</td></tr>\n</table>","G61":"<h1>agra</h1>\n<p>Strong n° 61 <i>Prononciation [ag'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chasse, pêche</li>\n<li>ce qui est pris à la chasse ou la pêche, butin, proie\n<ol type=\"a\">\n<li>oiseaux, bêtes</li>\n<li>poisson</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγρα</b> <b>ας (ἡ) :<br> 1</b> chasse, OD. <i>22, 306 ;</i> SOPH. <i>Aj. 407 ;</i> PLAT. <i>Leg. 823</i> e ; ἐς ἄγρας ἰέναι, EUR. <i>Suppl. 885,</i> aller à la chasse ; pêche, SOPH. <i>Aj. 880 ;</i><br><b> 2</b> gibier, proie, butin, OD. <i>12, 330 ;</i> HÉS. <i>Th. 412 ;</i> ESCHL. <i>Eum. 148 ;</i> SOPH. <i>Aj. 64 ; particul</i>. poisson qu’on prend à la pêche, NT. <i>Luc. 5, 9</i>.<p><b>➼</b> <i>Ion</i>. ἄγρη, OD. <i>22, 306 ;</i> HDT. <i>1, 73, 5</i>.</p><p><b>Étym</b>. <i>Etym. inconnue, p.-ê. pré-grec</i>.<b>Ἄγρα</b> <b>ας (ἡ)</b> Agra, <i>dème att. avec temple à Artémis</i> Ἀγραία, PLAT. <i>Phædr. 229</i> c ; PLUT. <i>Demetr. 26 ; postér. plur</i>. Ἄγραι, PLUT. <i>Herod. mal. 26</i>.</p><p><b>➼</b> <i>Dans les inscr. att. d’ord. au sg</i>. CIA. <i>1, 273, f. 23 (pas av. 420 av. J.C.) ; 2, 315, 9 (282/280 av. J.C.) ; plur. seul. sous l’empire,</i> CIA. <i>3, 319, v. Meisterh. p. 97, 22</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρα - ἄγρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2) => <a class=\"ref\" data-r=\"LUK5.4,9\">Luc 5.4,9</a></li>\n</ul>\n</td></tr>\n</table>","G62":"<h1>agrammatos</h1>\n<p>Strong n° 62 <i>Prononciation [ag-ram-mat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>illettré, non instruit, le bas peuple</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγράμματος</b> <b>ἀ·γράμματος, ος, ον</b> <font color=\"brown\">[μᾰ]</font> :<br><b> 1</b> qui ne sait pas lire <i>ou</i> écrire, illettré, ignorant, XÉN. <i>Mem. 4, 2, 20 ;</i> PLAT. <i>Tim. 23</i> a, <i>etc. ;</i><br><b> 2</b> non écrit, PLAT. <i>Pol. 295</i> a ;<br><b> 3</b> inarticulé, ARSTT. <i>Interpr. 2, 2 ;</i> DL. <i>3, 107 ;</i><br><b> 4</b> qui ne peut prononcer des sons articulés, ARSTT. <i>H.A. 1, 1, 29</i>.<br><font color=\"darkblue\">SEPT</font> sans formation rabbinique.<p><b>Étym</b>. ἀ, γράμμα.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-γραμματος - ἀγράμματος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT4.13\">Actes 4.13</a></li>\n</ul>\n</td></tr>\n</table>","G63":"<h1>agrauleo</h1>\n<p>Strong n° 63 <i>Prononciation [ag-row-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vivre dans les champs, à ciel ouvert, même la nuit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγραυλέω</b> <b>ἀγραυλέω-ῶ</b>, séjourner <i>ou</i> passer la nuit dans les champs, ARSTT. <i>Mir. 11 ;</i> PLUT. <i>Num. 4 ; en parl. de bergers,</i> NT. <i>Luc. 2, 8</i>. <i>p. ext.</i> se trouver <i>ou</i> vivre en plein air, vivre dans les champs.<p><b>Étym</b>. ἄγραυλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρ-αυλεω - ἀγραυλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK2.8\">Luc 2.8</a></li>\n</ul>\n</td></tr>\n</table>","G64":"<h1>agreuo</h1>\n<p>Strong n° 64 <i>Prononciation [ag-rew'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chasser, prendre à la chasse, attraper, prendre au piège</li>\n<li>métaph. poursuivre avec ardeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγρεύω</b> <font color=\"darkgreen\">(<i>f</i>. ἀγρεύσω, <i>ao</i>. ἤγρευσα, <i>pf</i>. ἤγρευκα ; <i>pass. ao</i>. ἠγρεύθην)</font><br><b> 1</b> prendre à la chasse <i>ou</i> à la pêche, <i>acc</i>. HDT. <i>2, 95 ;</i> XÉN. <i>Cyn. 12, 6, etc. ;</i> ἄγραν ἀγρεύειν, EUR. <i>Bacch. 434,</i> poursuivre <i>ou</i> prendre une proie ; ἄνδρας ἀγρ. SOPH. <i>fr. 498,</i> capturer des hommes ;<br><b> 2</b> <i>fig</i>. poursuivre, courir après, rechercher, <i>acc</i>. EUR. <i>Bacch. 138 ;</i> ANTH. <i>7, 196 ;</i><br><b><i>Moy</i></b>. poursuivre <i>ou</i> prendre à la chasse, <i>d’où</i> capturer, s’emparer de, <i>acc</i>. EUR. <i>I.T. 1163, etc</i>.<p><b>Étym</b>. ἀγρεύς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρευω - ἀγρεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK12.13\">Marc 12.13</a></li>\n</ul>\n</td></tr>\n</table>","G65":"<h1>agrielaios</h1>\n<p>Strong n° 65 <i>Prononciation [ag-ree-el'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>olivier sauvage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγριέλαιος</b> <b>ος, ον :<br> 1</b> d’olivier sauvage, ANTH. <i>9, 237 ;</i><br><b> 2</b> ἡ ἀγριέλαιος, olivier sauvage, <i>c</i>. ἀγριελαία, TH. <i>H.P. 2, 3, 5 ;</i> THCR. <i>Idyl. 7, 18 ;</i> NT. <i>Rom. 11, 17</i>.<br><font color=\"darkblue\">Étym.</font></b></i> ἄγριος, ἐλαία.<br><i><b><font color=\"red\">Ant.</font></b></i> καλλιέλαιος.<br><i><b><font color=\"purple\">Syn.</font></b></i> ἔλαιος, κότινος, πυρκαϊά, φυλία.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρι-ελαιος - ἀγριέλαιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (3) => <a class=\"ref\" data-r=\"ROM11.17,24\">Romains 11.17, 24</a></li>\n</ul>\n</td></tr>\n</table>","G66":"<h1>agrios</h1>\n<p>Strong n° 66 <i>Prononciation [ag'-ree-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vivant ou poussant dans les champs ou les bois\n<ol type=\"a\">\n<li>animaux sauvages</li>\n<li>terrains non cultivés, en friche</li>\n</ol>\n</li>\n<li>hommes et animaux sauvages, féroces\n<ol type=\"a\">\n<li>bourru, rude</li>\n<li>passion violente, véhémence, furie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄγριος</b> <b>α, ον :<br>   I</b> qui vit dans les champs, campagnard, MOSCH. <i>5, 15 ;</i><br><b>   II</b> <i>p. suite :</i><br><b> 1</b> sauvage, <i>en parl. d’animaux (p. opp. à</i> τιθασός <i>ou</i> ἥμερος) IL. <i>3, 24 ; 5, 52, etc. ; en parl. d’hommes vivant à l’état sauvage,</i> HDT. <i>4, 191 ; en parl. de fruits,</i> ESCHL. <i>Pers. 614 ;</i> SOPH. <i>Tr. 1197, etc. ; en parl. de terres, de pays non cultivés,</i> PLAT. <i>Phæd. 113</i> c, <i>etc. ;</i><br><b> 2</b> <i>au mor</i>. sauvage, farouche, violent, cruel, <i>en parl. de pers</i>. IL. <i>6, 97 ;</i> OD. <i>2, 19, etc. ;</i> ἄγριον εἰς ἡμᾶς ἔχεις, EUR. <i>El. 1116,</i> tu l’entretiens dans des dispositions farouches contre nous ; <i>en parl. de choses (passions, événements, etc</i>.) ἄ. χόλος, IL. <i>4, 23 ;</i> OD. <i>8, 304 ;</i> ἄ. θυμός, IL. <i>9, 629,</i> colère sauvage ; τὸ ἄγριον, PLAT. <i>Crat. 394</i> e sauvagerie ; <i>adv</i>. ἄγρια, HÉS. <i>Sc. 236</i> MOSCH. <i>1, 11,</i> d’une manière sauvage.<br><i>● Cp</i>. -ώτερος, HDT. <i>8, 13 ;</i> THC. <i>6, 60 ;</i> PLAT. <i>Leg. 720</i> e, <i>etc.</i> <i>● Sup. :</i> -ώτατος, HDT. <i>4, 106 ;</i> PLAT. <i>Rsp. 564</i> a, <i>etc</i>.<p><b>➼</b> <i>Fém</i>. ἄγριος, IL. <i>3, 24 ; 19, 88 ;</i> PLAT. <i>Leg. 824</i> a ; — <font color=\"brown\">[ῑ]</font> <i>dans</i> ἀγρίου IL. <i>22, 313</i>.</p><p><b>Étym</b>. ἀγρός.<b>Ἄγριος</b> <b>ου (ὁ)</b> Agrios, <i>h</i>. IL. <i>14, 117 ;</i> HÉS. <i>Th. 1013</i>.</p><p><b>Étym</b>. <i>cf</i>. ἄγριος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγριος - ἄγριος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT3.4\">Matthieu 3.4</a></li>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK1.6\">Marc 1.6</a></li>\n<li>Jude (1) => <a class=\"ref\" data-r=\"JUD1.13\">Jude 13</a></li>\n</ul>\n</td></tr>\n</table>","G67":"<h1>Agrippas</h1>\n<p>Strong n° 67 <i>Prononciation [ag-rip'-pas]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Agrippa = « cheval sauvage »\n<ol><li>Nom d'une famille gouvernante en Israël au temps de Christ</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Ἀγρίππας</b> <b>ου</b> <i>et</i> <b>α (ὁ)</b> Agrippa, <i>n. rom</i>. PLUT. <i>Ant. 35, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αγριππας - Ἀγρίππας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (11) => <a class=\"ref\" data-r=\"ACT25.13,22,23,24,26;26.1,2,19,27,28,32\">Actes 25.13, 22, 23, 24, 26 ; 26.1, 2, 19, 27, 28, 32</a></li>\n</ul>\n</td></tr>\n</table>","G68":"<h1>agros</h1>\n<p>Strong n° 68 <i>Prononciation [ag-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>terre\n<ol type=\"a\">\n<li>le champ, la campagne</li>\n<li>pièce de terrain</li>\n<li>les fermes, les hameaux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγρός</b> <b>οῦ (ὁ) :<br> 1</b> champ, <i>d’ord. au pl</i>. IL. <i>23, 832 ;</i> OD. <i>4, 757, etc. ; au sg</i>. bien de campagne, OD. <i>24, 205 ;</i><br><b> 2</b> la campagne, <i>p. opp. à la ville :</i> ἀγρῷ, OD. <i>11, 188 ;</i> ἐπ' ἀγροῦ, OD. <i>1, 185, 190, etc. ;</i> ἐν ἀγρῷ, XÉN. <i>Mem. 2, 9, 4 ;</i> AR. <i>fr. 344, 2 ;</i> ἐν ἀγροῖς, SOPH. <i>O.R. 112 ;</i> ἐπ' ἀγρῶν, SOPH. <i>O.R. 1049 ;</i> ἐπ' ἀγροῖς, PLUT. <i>Cic. 31 ;</i> ἀγροῖσι, SOPH. <i>El. 313 ;</i> κατ' ἀγρούς, PLAT. <i>Leg. 881</i> c, à la campagne, aux champs ; τὰ ἐξ ἀγρῶν, THC. <i>2, 13,</i> ce qui vient de la campagne.<p><b>➼</b> <font color=\"brown\">[α]</font> <i>mais toujours</i> <font color=\"brown\">[ᾰ]</font> <i>dans les Com. excepté</i> AR. <i>Av. 579 ;</i> PHILÉM. <i>fr. 21</i>.</p><p><b>Étym</b>. <i>R. indo-europ</i>. *h<sub>2</sub>eǵ-ro-, champ ; <i>cf. lat</i>. ăger, <i>sscr</i>. ájra- ; <i>probabl. de</i> *h<sub>2</sub>eǵ-, conduire, <i>v</i>. ἄγω, « terre en jachère où l’on conduisait le bétail ».</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρος - ἀγρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n36 fois dans 34 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (17)</li>\n<li>Marc (8)</li>\n<li>Luc (10)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G69":"<h1>agrupneo</h1>\n<p>Strong n° 69 <i>Prononciation [ag-roop-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être sans sommeil, éveillé, veiller</li>\n<li>être circonspect, attentif, prêt</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγρυπνέω</b> <b>ἀγρυπνέω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. ήσω, <i>ao</i>. ἠγρύπνησα, <i>pf</i>. ἠγρύπνηκα)</font><br><b> 1</b> être sans sommeil, être éveillé, THGN. <i>471 ;</i> HPC. <i>Progn. 37 ;</i> XÉN. <i>Cyr. 8, 3, 42 ;</i> ἀγρ. τὴν νύκτα, XÉN. <i>Hell. 7, 2, 19,</i> passer la nuit sans dormir ; <i>d’où</i> souffrir d’insomnie, DIOSC. <i>4, 65 ;</i><br><b> 2</b> <i>fig</i>. être vigilant, SPT. <i>Sap. 6, 15 ;</i> NT. <i>Marc. 13, 33</i>.<p><b>➼</b> <font color=\"brown\">[ῡ]</font> THCR. <i>Idyl. 10, 10 ; mais v</i>.ἀγρυπνητήρ, ἀγρυπνητικός, ἀγρυπνία, ἄγρυπνος.</p><b>3</b> <font color=\"darkblue\">SEPT</font> se réveiller.<br><i><b><font color=\"darkblue\">Étym.</font></b></i> ἄγρυπνος.<br><i><b><font color=\"red\">Ant.</font></b></i> καθεύδω.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρ-υπνεω - ἀγρυπνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK13.33\">Marc 13.33</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK21.36\">Luc 21.36</a></li>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH6.18\">Éphésiens 6.18</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB13.17\">Hébreux 13.17</a></li>\n</ul>\n</td></tr>\n</table>","G70":"<h1>agrupnia</h1>\n<p>Strong n° 70 <i>Prononciation [ag-roop-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>veille, non endormi, insomnie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγρυπνία</b> <b>ας (ἡ) :<br> 1</b> insomnie, veille, HPC. <i>Aph. 1244 ;</i> PLAT. <i>Crit. 43</i> b, <i>etc. ; au pl</i>. HDT. <i>3, 129 ;</i> AR. <i>Lys. 27 ;</i><br><b> 2</b> temps <i>ou</i> durée de la veille, PLAT. <i>Ax. 368</i> b.<p><b>➼</b> <i>Dat. pl. ion</i>. -ίῃσιν, HDT. <i>l. c. ;</i> <font color=\"brown\">[ῠπν]</font> THCR. <i>Idyl. 21, 37 ;</i> <font color=\"brown\">[ῑ]</font> OPP. <i>C. 3, 511</i>.</p><p><b>Étym</b>. ἄγρυπνος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγρυπνια - ἀγρυπνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2) => <a class=\"ref\" data-r=\"2CO6.5;11.27\">2 Corinthiens 6.5 ; 11.27</a></li>\n</ul>\n</td></tr>\n</table>","G71":"<h1>ago</h1>\n<p>Strong n° 71 <i>Prononciation [ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener, conduire, amener avec soi\n<ol type=\"a\">\n<li>mener en tenant en laisse (un animal)</li>\n<li>accompagner à un lieu</li>\n<li>emmener à un magistrat, à une cour de justice</li>\n</ol>\n</li>\n<li>conduire\n<ol type=\"a\">\n<li>guider, diriger</li>\n<li>amener vers quelque chose</li>\n<li>mouvoir, pousser : forces et influences sur l'esprit</li>\n</ol>\n</li>\n<li>célébrer une fête</li>\n<li>aller, partir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγῶ</b> <b>ῇς, ῇ</b>, <i>sbj. ao.2 pass. de</i> ἄγνυμι.<b>ἁγώ</b> <font color=\"brown\">[ᾱ]</font> <i>crase p</i>. ἃ ἐγώ, SOPH. <i>El. 259</i>.<b>ἄγω</b> <font color=\"brown\">[ᾰ]</font> <font color=\"darkgreen\">(<i>f</i>. ἄξω, <i>ao.2</i> ἤγαγον <font color=\"brown\">[ᾰ]</font>, <i>rar. ao.1</i> ἦξα, <i>pf</i>. ἦχα : <i>pass. f</i>. ἀχθήσομαι <i>ou</i> ἄξομαι, <i>ao</i>. ἤχθην, <i>pf</i>. ἦγμαι)</font><br><b>A <i>tr</i>.<br>   I</b> mener, conduire :<br><b> 1</b> <i>en gén. (p. opp. à</i> φέρειν) : δῶκε δ' ἄγειν γυναῖκα καὶ τρίποδα φέρειν, IL. <i>23, 512,</i> il donna la femme à conduire et le trépied à porter ; ἄγ. ὑποζύγια, XÉN. <i>An. 4, 5, 24 ;</i> ἵππους, XÉN. <i>Eq. 6, 4,</i> conduire des bêtes de somme, des chevaux ; βοῦν ἄγ. κεράων, OD. <i>3, 439 ;</i> ἄγ. ἵππον τῆς ἡνίας, XÉN. <i>Eq. 6, 9,</i> conduire un bœuf par les cornes, un cheval par la bride ; <i>avec double acc. :</i> ἄγ. τὸ στράτευμα τὴν ἐπὶ Μέγαρα (<i>s.-e</i>. ὁδόν) XÉN. <i>Hell. 4, 4, 13,</i> diriger l’armée par la route de Mégare ; <i>avec l’idée de « route » pour suj. :</i> ὁδὸς ἄγει εἰς, <i>acc</i>. SOPH. <i>O.R. 734,</i> la route conduit vers ; <i>cf</i>. PLAT. <i>Rsp. 435</i> d ; <i>fig</i>. διὰ πόνων ἄγ. τινά, EUR. <i>I.T. 998,</i> conduire qqn à travers des épreuves ; <i>avec un suj. de chose :</i> ποῖ ἡ ἐπιθυμία αὐτὸν ἄξει ; PLAT. <i>Rsp. 359</i> e, où le conduira le désir ? ;<br><b> 2</b> guider : τινά, EUR. <i>I.T. 988, etc</i>. qqn ; <i>abs</i>. τὰ ἴχνη ἄξει, XÉN. <i>Cyn. 8, 4,</i> les traces guideront ; <i>fig</i>. ἄγεσθαι λογισμῷ, PLAT. <i>Rsp. 431</i> c, être guidé pur le raisonnement ;<br><b> 3</b> <i>p. suite (avec l’idée d’autorité</i>) diriger, gouverner, commander : ἄγ. στρατιάν, ναῦς, THC. <i>7, 12 ; 8, 59, etc. ;</i> στρατόν, SOPH. <i>O.C. 1327 ;</i> XÉN. <i>Cyr. 1, 4, 17,</i> diriger une expédition, une flotte, une armée ; πόλιν, PLAT. <i>Leg. 771</i> b ; τὴν πολιτείαν, THC. <i>1, 127,</i> gouverner une cité, l’État ; <i>avec un suj. de chose :</i> ψυχὴ ἄγει πάντα, PLAT. <i>Leg. 896</i> e, l’âme dirige tout ; <i>abs</i>. ἄρχειν καὶ ἄγειν, PLAT. <i>Phædr. 237</i> d, commander et gouverner ; ἄγει ὁ θεὸς οὕτως, XÉN. <i>An. 6, 1, 18,</i> ainsi le veut la divinité ;<br><b> 4</b> <i>fig. en parl. d’éducation,</i> diriger, élever, former : παῖδας ἄγειν, LUC. <i>Anach. 20,</i> élever des enfants ; ὀρθῶς, καλῶς <i>ou</i> κακῶς ἀχθῆναι, PLAT. <i>Leg. 782</i> d, avoir été honnêtement, bien <i>ou</i> mal élevé ;<br><b>   II</b> mener avec soi (amener <i>ou</i> emmener) : κῆρυξ ἦλθεν ἄγων ἀοιδόν, OD. <i>8, 62,</i> le héraut arriva amenant un aède ; ἄγ. τινὰ μεθ' ἑαυτοῦ, XÉN. <i>Cyr. 5, 4, 38,</i> amener qqn avec soi ; <i>d’où le part</i>. ἄγων = σύν <i>ou</i> μετά : τοὺς θεράποντας ἄγων, XÉN. <i>An. 3, 3, 2,</i> avec ses serviteurs ; <i>cf. An. 4, 4, 10 ; 5, 4, 2 ; Hell. 3, 4, 10, etc. ;</i><br><b>   III</b> mener jusqu’à, <i>d’où :</i><br><b> 1</b> amener : <i>avec un rég. de pers., de chose personnifiée ou d’animal :</i> ἄγ. εἰς τόπον, ATT. amener dans un lieu ; <i>poét. avec l’acc. seul. :</i> ἄγ. οἴκους, ESCHL. <i>Pers. 862,</i> ramener (des hommes) dans leurs foyers ; ὑπὸ ζυγὸν ἄγ. ἵππους, IL. <i>5, 731,</i> amener des chevaux sous le joug ; ἄγ. εἰς δικαστήριον, PLAT. <i>Leg. 928</i> b ; εἰς δίκας <i>ou</i> εἰς τὴν δίκην, XÉN. <i>Mem. 2, 9, 1, etc. ;</i> εἰς κρίσιν, PLAT. <i>Leg. 856</i> c ; ἐπὶ τοὺς δικαστάς, PLAT. <i>ibid</i>. amener au tribunal, en justice, devant les juges ; <i>en ce sens</i> ἄγειν <i>abs</i>. PLAT. <i>Leg. 914</i> e, <i>Gorg. 527</i> a ; <i>fig</i>. ἄγ. τὰς ψυχὰς εἰς τὴν ἀρετήν, PLAT. <i>Rsp. 547</i> b, amener les âmes à la vertu ; εἰς φόϐον, POL. <i>3, 2, 2,</i> à la crainte, à craindre ; <i>avec un rég. de chose,</i> amener, apporter : ἄγ. δῶρα, XÉN. <i>Cyr. 5, 5, 12, etc</i>. apporter des présents ; ἄγ. ἀγώγιμα, PLAT. <i>Prot. 313</i> d, amener une cargaison ; <i>avec un suj. de chose :</i> οἶνον νῆες ἄγουσι, IL. <i>9, 72,</i> les navires apportent du vin ; νῆες πεζοὺς ἤγαγον, ESCHL. <i>Pers. 553,</i> les navires amenèrent des combattants de pied ; <i>fig</i>. ἄγ. πῆμα, IL. <i>24, 547,</i> amener, <i>càd</i>. causer une douleur ; ἄγ. ὕπνον, SOPH. <i>Ph. 638,</i> apporter <i>ou</i> procurer le sommeil ; <i>avec un inf</i>. ἡ πεπρωμένη ἄγει θανεῖν, EUR. <i>Hec. 43,</i> la destinée amène à mourir ;<br><b> 2</b> amener à soi, attirer : ὁ Μαγνήσιος λίθος τοὺς δακτυλίους σιδηροῦς ἄγει, PLAT. <i>Ion 533</i> d, la pierre de Magnésie (l’aimant) attire les anneaux de fer ; <i>fig</i>. πάντας ἤγαγε δοὺς ἀμνηστίαν, HDN <i>3, 4, 17,</i> il se les concilia tous en accordant une amnistie ; <i>en mauv. part,</i> attirer (dans un piège) EUR. <i>Hec. 1146 ;</i><br><b> 3</b> <i>p. suite,</i> faire venir, EUR. <i>I.T. 138 ;</i><br><b>   IV</b> emmener :<br><b> 1</b> (<i>sans idée de violence</i>) ἄγ. γυναῖκα, ESCHL. <i>Pr. 558,</i> emmener (chez soi) une femme (pour l’épouser) (<i>d’ord. en ce sens le Moy., v. ci-dessous</i>) ;<br><b> 2</b> (<i>avec idée de violence</i>) emporter, entraîner : ἄγ. πάντα, IL. <i>1, 367,</i> emporter tout (après le pillage d’une ville) ; ἄγειν λείαν, XÉN. <i>Cyr. 5, 3, 1,</i> emporter du butin ; ἵππους αἰχμαλώτους καὶ ἄνδρας ἄγ. XÉN. <i>Cyr. 4, 3, 1,</i> emmener prisonniers hommes et chevaux ; ἄγ. εἰς δουλείαν, ESCHN. <i>1, 62 Baiter-Sauppe, etc</i>. emmener en servitude ; ἄγ. καὶ φέρειν, HDT. <i>1, 88 ;</i> XÉN. <i>Cyr. 3, 2, 12 ; ou</i> φέρειν καὶ ἄγειν, XÉN. <i>3, 2, 2, etc</i>. piller, dévaster (<i>cf. lat</i>. agere et ferre, LIV. <i>12, 3, etc</i>.) ; φέρειν καὶ ἄγειν (<i>mais non</i> ἄγειν καὶ φέρειν) <i>signifie qqf</i>. porter en même temps <i>ou</i> ensemble, PLAT. <i>Phædr. 279</i> c, <i>Leg. 817</i> a ; XÉN. <i>Cyr. 3, 3, 2, etc. (cf. lat</i>. portari atque agi, CÆS. <i>B. C. 2, 25</i>) ; ἀγόμεθα καὶ φερόμεθα, EUR. <i>Tr. 1310,</i> nous sommes ruinés, perdus ; ἄγ. καὶ καίειν, XÉN. <i>Hell. 3, 2, 5,</i> piller et brûler, saccager ;<br><b> 3</b> entraîner avec soi par son poids, <i>d’où</i> peser ; ἄγ. μνᾶν, DÉM. <i>617, 21 ;</i> ἄγ. τριακοσίους δαρεικούς, DÉM. <i>741, 7,</i> peser une mine, 300 dariques ; <i>p. suite, fig</i>. peser, évaluer, estimer, apprécier (<i>cf. lat</i>. ducere) : θεὸν ἄγ. τινά, LUC. <i>Gall. 18,</i> regarder qqn comme un dieu ; ἄγ. περὶ πλείστου <i>avec l’inf</i>. HDT. <i>9, 7,</i> attacher une extrême importance ; ἐν τιμῇ ἄγ. ATT. ; ἐντίμως ἄγ. PLAT. <i>Rsp. 528</i> c ; διὰ τιμῆς ἄγ. LUC. <i>Prom. 4,</i> avoir en honneur, faire cas de, estimer ; τιμιώτερον ἄγ. THC. <i>8, 81,</i> faire plus de cas de ; πρόσθεν ἄγ. τινά τινος, EUR. <i>Bacch. 225,</i> préférer une divinité à une autre ; ὡς παρ' οὐδὲν ἄγ. SOPH. <i>Ant. 34,</i> ne faire aucun cas de ; ἐν οὐδεμιῇ μοίρῃ μεγάλῃ ἄγ. τινά, HDT. <i>2, 172,</i> ne pas professer une grande estime pour qqn ; <i>au pass</i>. ἠγόμην δ' ἀνὴρ ἀστῶν μέγιστος, SOPH. <i>O.R. 775,</i> je tenais le premier rang dans la cité ;<br><b>   V</b> mener en avant, pousser devant soi :<br><b> 1</b> <i>au propre :</i> ἄγ. τεῖχος, THC. <i>6, 99,</i> construire un mur ; ἄγ. ὕδωρ, PLAT. <i>Leg. 844</i> b ; ὄγμον, THCR. <i>Idyl. 10, 2 ;</i> τάφρον, PLUT. <i>Ages. 39,</i> creuser un conduit d’eau, un canal, un fossé ; γραμμάς, ARSTT. <i>Top. 1, 1, 6,</i> tracer des lignes ;<br><b> 2</b> <i>avec idée de temps ;</i> ἡμέραν ἄγ. XÉN. <i>Cyr. 7, 1, 7,</i> passer le jour ; <i>cf</i>. SOPH. <i>El. 266 ;</i> EUR. <i>Cycl. 402 ; p. anal</i>. ἄγ. ἑορτήν, HDT. <i>1, 147, etc. ;</i> μυστήρια, XÉN. <i>Hell. 1, 4, 8 ;</i> θυσίας, PLAT. <i>2 Alc. 148</i> e, célébrer une fête, des mystères, des sacrifices ; <i>de même, en gén. (avec idée de durée, de prolongation</i>) ἄγ. σχολήν, PLAT. <i>Theæt. 172</i> b = σχολάζειν, être de loisir ; ἄγ. ἡσυχίαν, XÉN. <i>Hell. 1, 4, 18</i> = ἡσυχεῖν, être en repos ; ἄγ. εἰρήνην, XÉN. <i>An. 2, 6, 4,</i> être en paix ; ἄγ. πόλεμον, DÉM. <i>5, 19 Baiter-Sauppe,</i> être en guerre ; ἄγ. εὐδαιμονίαν, EUR. <i>Hipp. 750,</i> être heureux ; ἄγ. γέλωθ' (<i>dev. un esprit rude</i>) SOPH. <i>Aj. 382,</i> rire ; ἄγ. πένθος, LUC. <i>Tim. 22,</i> être dans le deuil, <i>etc. ;</i><br><b> 3</b> <i>p. suite,</i> maintenir, conserver : ἐλευθέραν ἦγε τὴν Ἑλλάδα, DÉM. <i>120, 17,</i> il maintenait la Grèce libre ; <i>d’où</i> conserver dans la mémoire : καί μευ κλέος ἦγον Ἀχαιοί, OD. <i>5, 311,</i> et les Grecs conserveraient le souvenir de mon nom ;<br><b>B</b> <i>intr. en apparence</i> (<i>s.-e</i>. στρατόν <i>ou</i> ἑαυτόν) se pousser en avant, s’avancer, <i>d’ord. en parl. d’un chef d’armée :</i> καιρός ἐστιν ἄγ. ἐπὶ τοὺς πολεμίους, XÉN. <i>Cyr. 3, 3, 46,</i> il est temps de marcher à l’ennemi ; ἦγε ταχέως, XÉN. <i>An. 4, 1, 17, etc</i>. il s’avançait rapidement ; <i>p. suite, en parl. des soldats eux-mêmes, ou, en gén., d’une troupe :</i> ταύτῃ ἄξει ὁ λόχος, XÉN. <i>An. 4, 8, 12,</i> c’est par là que s’avancera la compagnie ; <i>cf</i>. PLAT. <i>Leg. 701</i> e ;<br><b>C</b> <i>emploi particulier du part. et de l’impér. présent :</i><br><b>   I</b> <i>part. :</i> ἄγων <i>joint à un verbe à un mode personnel a la même valeur que s’il était lui-même au mode et au temps de ce verbe :</i> στῆσε δ' ἄγων (νῆας) IL. <i>2, 558,</i> il amena les navires et les arrêta ; <i>cf</i>. OD. <i>1, 130 ;</i><br><b>   II</b> <i>impér. : l’impér. équivaut à une sorte d’interj. : v</i>. ἄγε, ἄγετε ;<br><b>Moy. ἄγομαι</b> <font color=\"darkgreen\">(<i>f</i>. ἄξομαι, <i>ao.2</i> ἠγαγόμην <font color=\"brown\">[ᾰ]</font>, <i>pf</i>. ἦγμαι)</font><br><b>   I</b> mener, amener <i>ou</i> emmener pour soi <i>ou</i> avec soi :<br><b> 1</b> <i>en parl. de choses :</i> χρυσόν τε καὶ ἄργυρον οἴκαδ' ἄγ. OD. <i>10, 35,</i> emporter dans son pays de l’or et de l’argent ; ἄγ. φορτία, XÉN. <i>Œc. 8, 12,</i> emporter des marchandises ;<br><b> 2</b> <i>particul. avec ou sans</i> γυναῖκα, épouser une femme (<i>litt</i>. l’emmener chez soi) HDT. <i>5, 90 ;</i> THC. <i>8, 21 ;</i> ἄγεσθαι <i>se dit aussi du père qui fait épouser une femme à son fils,</i> OD. <i>4, 10 ;</i> HDT. <i>1, 34 ; 9, 111, etc. ; du frère qui amène une femme à son frère,</i> OD. <i>15, 238 ; des amis du fiancé qui amènent la femme chez son époux,</i> OD. <i>6, 28 ;</i><br><b> 3</b> <i>p. suite,</i> entraîner par son poids, <i>d’où</i> peser, évaluer, estimer : ἄγεσθαι ἐν τιμῇ, HDT. <i>1, 134 ; 2, 83,</i> avoir en honneur ;<br><b>   II</b> amener <i>ou</i> attirer à soi : ἄγονται ὑφ' ἑαυτὰς τοὺς νεοττούς, ARSTT. <i>H.A. 9, 1,</i> elles attirent leurs petits sous elles ; <i>fig</i>. ἄγεσθαί τινα σύμμαχον, XÉN. <i>Cyr. 1, 6, 11,</i> amener qqn dans son alliance ; ἄγεσθαί τι ἐς χεῖρας, HDT. <i>1, 126 ; 4, 79,</i> prendre une entreprise en main, s’en charger ;<br><b>   III</b> mener en avant, pousser, produire au dehors : διὰ στόμα μῦθον ἄγεσθαι, IL. <i>14, 91, litt</i>. ouvrir la bouche et émettre un avis.<p><b>➼</b> <i>Pf</i>. ἀγήοχα <i>seul. en composition. Pf. pass</i>. ἦγμαι <i>au sens moy</i>. JOS. <i>A.J. 18, 9, 5. Fut. moy</i>. ἄξομαι <i>au sens pass</i>. ESCHL. <i>Ag. 1632 ;</i> PLAT. <i>Rsp. 458</i> d. <i>Formes épq. ou dialectales : Act. prés. ind. 3 pl. dor</i>. ἄγοντι, PD. <i>P. 7, 13 ; sbj. 3 sg</i>. ἄγῃσι, OD. <i>6, 37 ; inf. épq</i>. ἀγέμεν, IL. <i>7, 420 ; inf. eol</i>. ἄγην, SAPPH. <i>1, 19. Impf. dor</i>. ἆγον, PD. <i>P. 9, 123 ;</i> ESCHL. <i>Pers. 863, etc. poét</i>. ἄγον <font color=\"brown\">[ᾰ]</font> IL. <i>7, 312 ;</i> PD. <i>P. 5, 76 ; 3 duel</i> ἀγέτην <font color=\"brown\">[ᾰ]</font> OD. <i>3, 439. Fut. ind. 3 pl. dor</i>. ἄξοισι, PD. <i>P. 6, 13 ; inf. épq</i>. ἀξέμεναι, OD. <i>23, 221, ou</i> ἀξέμεν, IL. <i>23, 668. Ao.1 avec formes de fut. ou d’ao.2 : impér. 2 pl. épq</i>. ἄξετε, IL. <i>3, 105 ;</i> OD. <i>14, 414 ; inf</i>. ἀξέμεναι, IL. <i>23, 50 ;</i> HH. <i>Cer. 443, ou</i> ἀξέμεν, IL. <i>23, 111 : 24, 663 ;</i> HH. <i>Ap. 103. Ao.2 dor</i>. ἄγαγον <font color=\"brown\">[ᾱᾰ]</font> PD. <i>O. 2, 51 ;</i> SOPH. <i>Tr. 858 ;</i> THCR. <i>Idyl. 15, 103 ; poét</i>. ἄγαγον <font color=\"brown\">[ᾰᾰ]</font> IL. <i>11, 112 ; 24, 764 ;</i> EUR. <i>I.T. 138 ; sbj. 3 sg. épq</i>. ἀγαγῇσι, IL. <i>24, 155. Ao. itér</i>. ἄγεσκον <font color=\"brown\">[ᾰ]</font> HDT. <i>1, 148 ;</i> A. RH. <i>1, 849. Moy. ao.1 épq. sans augm. 2 pl</i>. ἄξεσθε, IL. <i>8, 505 (var</i>. ἄξασθε) ; <i>3 pl</i>. ἄξοντο (<i>var</i>. ἄξαντο) IL. <i>8, 545. Ao.2 dor</i>. ἀγαγόμην <font color=\"brown\">[ᾱᾰ]</font> EUR. <i>Andr. 104 conj</i>.</p><p><b>Étym</b>. <i>R. indo-europ</i>. *h₂eǵ-, mener ; <i>cf</i>. ὄγμος, <i>lat</i>. agō, <i>sscr</i>. ájati.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγω - ἄγω</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n73 fois dans 71 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (6)</li>\n<li>Luc (14)</li>\n<li>Jean (13)</li>\n<li>Actes (27)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G72":"<h1>agoge</h1>\n<p>Strong n° 72 <i>Prononciation [ag-o-gay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>conduite</li>\n<li>manière de vivre, éducation, discipline, comportement\n<ol type=\"a\">\n<li>chemin de la vie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγωγή</b> <b>ῆς (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> action de transporter :<br><b> 1</b> transport, HDT. <i>6, 85 ; au plur</i>. PLAT. <i>Rsp. 370</i> e ; ἀγ. τινος ἔς τινα, THC. <i>5, 85,</i> transport <i>ou</i> comparution devant qqn à l’instigation de qqn ; ἀγ. τοῦ ποδός, PLAT. <i>Rsp. 400</i> c, mouvement du pied ; ἀγ. ἐπί τι, HPC. <i>Epid. 1, 938,</i> tendance vers qqe ch. ;<br><b> 2</b> action d’amener <i>ou</i> d’emmener, ESCHL. <i>Ag. 1263 ;</i> SOPH. <i>O.C. 662 ;</i><br><b> 3</b> apport devant un magistrat d’un objet dont la possession était contestée, POL. <i>12, 16, 7, 8 et 14 ;</i><br><b>   II</b> action de conduire, de diriger, de guider : ἀγ. ἵππου, XÉN. <i>Eq. 6, 4,</i> action de diriger un cheval ; <i>particul</i>. conduite d’une troupe, d’une armée, PLAT. <i>Leg. 746</i> d ; ἐν ταῖς ἀγωγαῖς, XÉN. <i>Cyr. 6, 1, 25,</i> dans les marches ; <i>t. de balist</i>. manœuvre (d’une machine de jet) : ἐν ταῖς συνεχέσιν ἀγωγαῖς, PHIL. BYZ. en service <i>ou</i> fonctionnement continu ; <i>fig. :</i><br><b> 1</b> direction des affaires publiques, POL. <i>3, 8, 5 ;</i><br><b> 2</b> direction de l’esprit, éducation, PLAT. <i>Leg. 659</i> d ; ARSTT. <i>Nic. 10, 9, 8 ;</i> POL. <i>1, 32, 1 ;</i><br><b> 3</b> culture d’une plante, TH. <i>H.P. 1, 3, 2 ;</i><br><b> 4</b> manière de traiter une question, méthode, ARSTT. <i>Rhet. 1, 15, 10 ;</i><br><b> 5</b> direction particulière, <i>en parl. de doctrines, de sciences, d’arts, etc. ; d’où</i> école <i>ou</i> secte de philosophie, SEXT. <i>P. 1, 145 ;</i><br><b> 6</b> mouvement, <i>en musique,</i> PLUT. <i>M. 1141</i> c ;<br><b> 7</b> <i>pass</i>. le fait d’être guidé : τοῦ νόμου, τοῦ λογισμοῦ, PLAT. <i>Leg. 645</i> a, <i>etc</i>. par la loi, par le raisonnement.<p><b>Étym</b>. ἄγω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγωγη - ἀγωγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1) => <a class=\"ref\" data-r=\"2TI3.10\">2 Timothée 3.10</a></li>\n</ul>\n</td></tr>\n</table>","G73":"<h1>agon</h1>\n<p>Strong n° 73 <i>Prononciation [ag-one']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une assemblée,\n<ol type=\"a\">\n<li>lieu d'assemblée : spécialement pour voir des jeux</li>\n<li>lieu de la manifestation : arène ou stade</li>\n</ol>\n</li>\n<li>l'assemblée des Grecs à leurs jeux nationaux\n<ol type=\"a\">\n<li>lutte pour le prix, course, lutte, concours athlétique</li>\n<li>un combat, combat contre les obstacles</li>\n<li>une action en justice, un procès</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγών</b> <b>ῶνος (ὁ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> assemblée, réunion : ἀγ. θεῖος, IL. <i>7, 298,</i> assemblée des dieux, <i>càd</i>. l’endroit où sont rassemblées les statues des dieux (<i>sel. d’autres,</i> l’emplacement où le peuple se rassemble pour prier devant le temple) ; <i>d’où</i> emplacement pour une réunion : ἀγ. θεῖος, IL. <i>18, 376,</i> le lieu de l’Olympe où s’assemblent les dieux ; ἀγ. νεῶν, IL. <i>16, 239,</i> l’endroit où la flotte est mouillée ;<br><b>   II</b> <i>particul</i>. assemblée pour des jeux publics, IL. <i>23, 258 ; 24, 1 ;</i> OD. <i>8, 200 ; d’où</i> emplacement pour ces jeux, arène : καλὸν δ' εὔρυναν ἀγῶνα, OD. <i>8, 260,</i> ils disposèrent une vaste et belle arène ; <i>en parl. de l’</i>assemblée des Grecs pour les grands jeux nationaux, HDT. <i>2, 91 ;</i> THC. <i>3, 104 ;</i> SOPH. <i>El. 682 ;</i> PLAT. <i>Leg. 658</i> a : <i>d’où :</i><br><b> 1</b> emplacement pour ces jeux (pour les concurrents comme pour les spectateurs) THC. <i>5, 50 ;</i><br><b> 2</b> les jeux eux-mêmes, jeux, concours, lutte : ἀγῶνα τιθέναι, HDT. <i>2, 91,</i> instituer des jeux publics ; ἀγ. ἱππικός, HDT. <i>2, 91,</i> jeux équestres (<i>càd</i>. course de chars, course en selle) ; γυμνικός, PLAT. <i>Leg. 658</i> a, jeux gymniques (<i>càd</i>. lutte, combat du ceste, course à pied, <i>etc</i>.) : ἀγ. μουσικός, THC. <i>3, 104 ;</i> AR. <i>Pl. 1163 ;</i> concours de musique <i>ou</i> de poésie ; ἀγῶνες στεφανηφόροι, HDT. <i>5, 102, ou</i> στεφανῖται, ARSTT. <i>Rhet. 1, 2, 13 ;</i> PLUT. <i>Dem. 6,</i> concours où l’on décerne des couronnes ; <i>p. ext</i>. ὁ ἀγών, pièce de théâtre, PLUT. <i>Dem. 22 ;</i><br><b> 3</b> but proposé aux concurrents : βαλεῖν ἔξω τοῦ ἀγῶνος, PD. <i>P. 1, 44 ; ou sans</i> βαλεῖν, LUC. <i>Gymn. 21,</i> frapper hors du but, <i>càd</i>. s’écarter du sujet ;<br><b>   III</b> <i>p. ext</i>. lutte, combat :<br><b> 1</b> action militaire, combat, bataille, THC. <i>2, 89 ;</i><br><b> 2</b> lutte judiciaire, procès, ESCHL. <i>Eum. 677, 744 ;</i> XÉN. <i>Lac. 8, 4 ;</i> PLAT. <i>Ap. 24</i> c, <i>etc. ; surt</i>. grand procès, PLUT. <i>Dem. c. Cic. 1 ;</i><br><b> 3</b> lutte, <i>en gén</i>. SOPH. <i>Tr. 20, 159, etc. ;</i> ἀγ. περὶ τῆς ψυχῆς, EUR. <i>Or. 837,</i> lutte pour la vie ;<br><b> 4</b> <i>p. suite,</i> objet d’une lutte, <i>d’où</i> débat, question, intérêt en jeu, HDT. <i>7, 105 ;</i><br><b> 5</b> danger, péril : πολλοὺς ἀγῶνας δραμέονται, HDT. <i>8, 102,</i> ils courront beaucoup de dangers ;<br><b> 6</b> <i>p. ext</i>. moment critique : ποιέειν ἢ παθέειν πρόκειται ἀγών, HDT. <i>7, 11,</i> agir <i>ou</i> souffrir (l’agrandissement de la Grèce), voilà de quoi il s’agit ; ἀγὼν πρόφασιν οὐ δέχεται, AR. <i>fr. 318,</i> la circonstance n’admet pas de prétexte ; οὐ λόγων ἐσθ' ἁγών (<i>p</i>. ὁ ἀγ.) EUR. <i>Ph. 588,</i> ce ne sont pas des paroles que réclame la circonstance ;<br><b> 7</b> crainte, anxiété, THC. <i>7, 71 ;</i> POL. <i>4, 56, 4</i>.<p><b>Étym</b>. ἄγω.<b>Ἀγών</b> <b>ῶνος (ὁ)</b> <font color=\"brown\">[ᾰ]</font> Agôn, <i>dieu protecteur des jeux publics,</i> PAUS. <i>5, 20, 3, etc</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγων - ἀγών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Philippiens (1) => <a class=\"ref\" data-r=\"PHP1.30\">Philippiens 1.30</a></li>\n<li>Colossiens (1) => <a class=\"ref\" data-r=\"COL2.1\">Colossiens 2.1</a></li>\n<li>1 Thessaloniciens (1) => <a class=\"ref\" data-r=\"1TH2.2\">1 Thessaloniciens 2.2</a></li>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI6.12\">1 Thimothée 6.12</a></li>\n<li>2 Timothée (1) => <a class=\"ref\" data-r=\"2TI4.7\">2 Thimothée 4.7</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB12.1\">Hébreux 12.1</a> </li>\n</ul>\n</td></tr>\n</table>","G74":"<h1>agonia</h1>\n<p>Strong n° 74 <i>Prononciation [ag-o-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une lutte pour la victoire\n<ol type=\"a\">\n<li>exercice de gymnastique</li>\n</ol>\n</li>\n<li>émotions et sévères luttes mentales, angoisse, agonie, anxiété, inquiétude</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγωνία</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰγ]</font> :<br><b> 1</b> lutte dans les jeux, XÉN. <i>Cyr. 2, 3, 15 ;</i> DÉM. <i>1398, 20 ; d’où</i> exercice gymnastique, HPC. <i>Art. 787 ;</i> PLAT. <i>Men. 94</i> b, <i>etc. ; p. suite,</i> exercice, <i>en gén</i>. PLAT. <i>Gorg. 456</i> d, <i>etc. ;</i><br><b> 2</b> lutte, <i>en gén</i>. HDT. <i>2, 91 ;</i> EUR. <i>Hec. 314 ; fig</i>. agitation de l’âme, inquiétude, anxiété, angoisse, DÉM. <i>236, 19 ;</i> ARSTT. <i>Probl. 2, 26, etc</i>.<p><b>➼</b> <i>Ion</i>. -ίη, HDT. <i>2, 91, etc</i>.</p><p><b>Étym</b>. ἀγών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγωνια - ἀγωνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK22.44\">Luc 22.44</a></li>\n</ul>\n</td></tr>\n</table>","G75":"<h1>agonizomai</h1>\n<p>Strong n° 75 <i>Prononciation [ag-o-nid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entrer en lutte : lutter dans des jeux sportifs</li>\n<li>lutter avec des adversaires, combattre</li>\n<li>métaph. lutter avec les difficultés et les dangers</li>\n<li>s'efforcer d'avoir un extrême zèle ; obtenir quelque chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀγωνίζομαι</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> <i>dép. (f</i>. ἀγωνιοῦμαι, <i>postér</i>. ἀγωνίσομαι, <i>ao</i>. ἠγωνισάμην, <i>pf</i>. ἠγώνισμαι) :<br><b> 1</b> concourir dans les jeux publics, lutter, disputer le prix, HDT. <i>2, 160 ;</i><br><b> 2</b> combattre, lutter, <i>en gén. :</i> περί τινος, THC. <i>6, 16,</i> pour qqe ch. : πρός τινα, THC. <i>1, 36,</i> contre qqn ; ἀγ. ἀγῶνα, EUR. <i>Suppl. 427 ;</i> μάχην, PLUT. <i>Per. 10,</i> soutenir une lutte, un combat ; ἀγ. στάδιον, HDT. <i>5, 22,</i> disputer le prix du stade ; <i>t. de droit :</i> ἀγ. δίκην, LYS. <i>98, 14 ;</i> DÉM. <i>653, 26,</i> soutenir un procès ; ἀγ. ψευδομαρτυριῶν (<i>s.-e</i>. δίκην) DÉM. <i>741, 20,</i> se défendre contre des déclarations de faux témoins ; ἀγ. φόνον, EUR. <i>Andr. 336,</i> avoir à se défendre contre une accusation de meurtre ; ἀγ. λόγον, PLUT. <i>Dem. 15,</i> prononcer un plaidoyer ; <i>p. anal</i>. ἀγ. δρᾶμα, <i>en parl. du poète,</i> faire représenter une pièce, ARSTT. <i>Poet. 7, 11 ; ou, en parl. de l’acteur,</i> jouer une pièce, DÉM. <i>418, 5 ; p. ext</i>. lutter, se donner de la peine, faire effort. LYS. <i>160, 6 ;</i> ἃ ἠγωνίσω, DÉM. <i>420, 4,</i> les efforts que tu as faits ;<br><b>   II</b> <i>pass. (f</i>. ἀγωνισθήσομαι, <i>qqf</i>. ἀγωνιοῦμαι ; <i>ao</i>. ἠγωνίσθην ; <i>pf</i>. ἠγώνισμαι) :<br><b> 1</b> être l’objet d’une lutte, d’un combat : πολλοὶ ἀγῶνες ἀγωνίδαται (<i>ion</i>.) HDT. <i>9, 26, 7,</i> beaucoup de luttes ont été soutenues ;<br><b> 2</b> <i>t. de droit,</i> être débattu, <i>en parl. d’une loi, d’une affaire,</i> DÉM. <i>709, 7 ;</i> τὰ ἠγωνισμένα, EUR. <i>Suppl. 465 ;</i> DÉM. <i>745, 21,</i> les points controversés.<p><b>➼</b> <i>Prés. d’ord. act., mais pass</i>. DÉM. <i>l. c. Fut</i>. ἀγωνιοῦμαι, <i>d’ord. act., mais pass</i>. DÉM. <i>516, 18. Fut. pass</i>. ἀγωνισθήσομαι, <i>seul</i>. ARSTD. <i>39, 504. Fut. moy</i>. ἀγωνίσομαι, <i>seul</i>. DS. <i>13, 21 dout. Ao. dor</i>. ἀγωνισάμαν <font color=\"brown\">[ᾰγ]</font> ANTH. <i>11, 81 ; pf. 3 pl. ion</i>. ἀγωνίδαται, HDT. <i>9, 26, 7</i>.</p><p><b>Étym</b>. ἀγών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αγωνιζομαι - ἀγωνίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK13.24\">Luc 13.24</a></li>\n<li>Jean (1) => <a class=\"ref\" data-r=\"JHN18.36\">Jean 18.36</a></li>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO9.25\">1 Corinthiens 9.25</a></li>\n<li>Colossiens (2) => <a class=\"ref\" data-r=\"COL1.9;4.12\">Colossiens 1.9 ; 4.12</a></li>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI6.12\">1 Timothée 6.12</a></li>\n<li>2 Timothée (1) => <a class=\"ref\" data-r=\"2TI4.7\">2 Timothée 4.7</a></li>\n</ul>\n</td></tr>\n</table>","G76":"<h1>Adam</h1>\n<p>Strong n° 76 <i>Prononciation [ad-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Adam = « la terre rouge »\n<ol><li>Adam, le premier homme, père de tout le genre humain</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀδάμ</b> <b>(ὁ)</b> <i>indécl</i>. Adam, <i>h</i>. ANTH. <i>1, 46 etc</i>.<p><b>Étym</b>. <i>mot hébr</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αδαμ</font> &lt; אדם - <font face=\"Georgia\">Ἀδάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK3.38\">Luc 3.38</a></li>\n<li>Romains (2) => <a class=\"ref\" data-r=\"ROM5.14\">Romains 5.14</a></li>\n<li>1 Corinthiens (3) => <a class=\"ref\" data-r=\"1CO15.22,45\">1 Corinthiens 15.22,45</a></li>\n<li>1 Timothée (2) => <a class=\"ref\" data-r=\"1TI2.13,14\">1 Timothée 2.13,14</a></li>\n<li>Jude (1) => <a class=\"ref\" data-r=\"JUD1.14\">Jude 14</a></li>\n</ul>\n</td></tr>\n</table>","G77":"<h1>adapanos</h1>\n<p>Strong n° 77 <i>Prononciation [ad-ap'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans dépense, ne coûtant rien, gratuit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀδάπανος</b> <b>ἀ·δάπανος, ος, ον</b> <font color=\"brown\">[δᾰᾰ]</font> :<br><b> 1</b> <i>pass</i>. non dispendieux, peu coûteux, AR. <i>Pax 593 ;</i> TÉLÈS (STOB. <i>Fl. 69, 19</i>) ;<br><b> 2</b> <i>act</i>. qui ne dépense pas, <i>gén</i>. ARSTT. <i>Virt. et vit. 7, 3</i>.<br><i>● Sup</i>. -ώτατος, PLUT.<p><b>Étym</b>. ἀ, δαπάνη.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδαπανος - ἀδάπανος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO9.18\">1 Corinthiens 9.18</a></li>\n</ul>\n</td></tr>\n</table>","G78":"<h1>Addi</h1>\n<p>Strong n° 78 <i>Prononciation [ad-dee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Addi = « ornement »\n<ol><li>fils de Kosam, et père de Melchi dans la généalogie du Seigneur</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αδδι</font> &lt; אדי - <font face=\"Georgia\">Ἀδδί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK3.28\">Luc 3.28</a></li>\n</ul>\n</td></tr>\n</table>","G79":"<h1>adelphe</h1>\n<p>Strong n° 79 <i>Prononciation [ad-el-fay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une propre sœur</li>\n<li>sœur amenée par le lien de la religion chrétienne</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδελφή</b> <b>ἀ·δελφή, ῆς (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> sœur, ATT. ;<br><b>   II</b> <i>p. anal</i>. sœur :<br><b> 1</b> <i>en parl. d’une parente, en gén</i>. SPT. <i>Tob. 8, 7 ; Job 42, 11 ;</i><br><b> 2</b> <i>t. d’affect. en parl. d’une épouse,</i> SPT. <i>Tob. 5, 21 ;</i> CANT. <i>4, 9 ;</i><br><b> 3</b> <i>au sens relig</i>. femme faisant partie de la communauté chrétienne, NT. <i>Rom. 16, 1 ; 1Cor. 7, 15 ; 9, 5 ; postér. en parl. de religieuses,</i> BAS. <i>3, 1153, 1156 Migne</i>.<p><b>➼</b> <i>Ion</i>. ἀδελφεή, HDT. <i>2, 56, etc. ; épq</i>. -ειή, Q. SM. <i>10 ; dor</i>. -εά, PD. <i>N. 7, 4 ;</i> SOPH. <i>O.R. 160, etc. ; éol</i>. -ία, ALC.</p><p><b>Étym</b>. <i>cf</i>. ἀδελφός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδελφη - ἀδελφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 24 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Jean (6)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>2 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G80":"<h1>adelphos</h1>\n<p>Strong n° 80 <i>Prononciation [ad-el-fos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un frère, qu'il soit né des deux mêmes parents ou seulement du même père ou de la même mère</li>\n<li>ceux qui ont le même ancêtre national, appartenant au même peuple</li>\n<li>tout compagnon, ou homme</li>\n<li>un croyant, uni aux autres par le lien de l'affection</li>\n<li>un associé dans le travail ou les fonctions</li>\n<li>frère en Christ\n<ol type=\"a\">\n<li>ses frères par le sang</li>\n<li>tous les hommes</li>\n<li>les apôtres</li>\n<li>chrétiens, ceux qui sont élevés vers le même lieu céleste</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδελφός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>A</b> <i>subst. :</i><br><b>   I</b> <i>pr</i>. frère, ATT. <i>etc. ; au pl</i>. ἀδελφοί, frères, ATT. ; <i>qqf</i>. frère et sœur, EUR. <i>El. 536 ;</i> ἀδελφεοὶ (<i>ion</i>.) ἀπ' ἀμφοτέρων, HDT. <i>7, 97,</i> frères de père et de mère ;<br><b>   II</b> <i>p. anal</i>. frère :<br><b> 1</b> <i>en parl. d’un parent en gén</i>. SPT. <i>Gen. 13, 8 ; Job 42, 11, etc. ;</i><br><b> 2</b> <i>homme de la même nation ou de la même tribu,</i> SPT. <i>Ex. 2, 11 ; 4, 18 ; Lev. 19, 17, etc. ;</i><br><b> 3</b> collègue, confrère, SPT. <i>2Esdr. 3, 2 ; Job 30, 39 ;</i> NT. <i>1Cor. 1, 1, etc. ;</i><br><b> 4</b> <i>t. d’affect. en parl. d’un ami,</i> SPT. <i>Tob. 5, 11 ; Judith 7, 30 ;</i><br><b> 5</b> <i>membre de la communauté chrétienne,</i> NT. <i>Ap. 9, 30 ; 28, 15, etc. ; postér</i>. religieux, BAS. <i>4, 356 Migne ;</i><br><b> 6</b> <i>t. de courtoisie entre souverains,</i> JOS. <i>A.J. 13, 2, 2 ;</i><br><b>B</b> <i>adj. :</i><br><b> 1</b> de frère <i>ou</i> de sœur, fraternel, ESCHL. <i>Sept. 811 ;</i> PLAT. <i>Criti. 109</i> c ;<br><b> 2</b> qui est par couple, double, jumeau : τὰ ἀδελφά, XÉN. <i>Mem. 2, 3, 49,</i> les organes jumeaux (yeux, mains, pieds, <i>etc</i>.) ;<br><b> 3</b> proche parent, semblable, analogue : τινος, SOPH. <i>Ant. 492 ;</i> PLAT. <i>Phæd. 108</i> b, <i>etc. ou</i> τινι, SOPH. <i>O.C. 1262, etc</i>. à qqn <i>ou</i> à qqe ch.<p><b>➼</b> <i>Voc</i>. ἄδελφε (<i>non</i> ἀδελφέ) <i>sel. les Gramm. Par crase</i> ἁδελφός = ὁ ἀδ. PLAT. <i>Prot. 310</i> c ; ἁδελφοί = οἱ ἀδ. CIG. <i>1, 8</i> b, <i>10 (av. 570 av. J.C. ; v. Meisterh. p. 56, 4). Dans Hom. ion</i>. ἀδελφεός, IL. <i>2, 586, ou épq</i>. ἀδελφειός, IL. <i>5, 21, etc. ; dans</i> HÉRODICUS <i>et</i> PD. ἀδελφεός ; <i>de même</i> ESCHL. <i>Sept. 974. Duel</i> ἀδελφεώ, THCR. <i>Idyl. 24, 8</i>.</p><p><b>Étym</b>. ἀ <i>cop</i>. δελφύς, <i>litt</i>. « né du même sein »; <i>cf</i>. ἀγάστωρ ; <i>voy</i>. ἀδελφή.<br><font color=\"purple\">Syn.</font></b></i> κασίγνητος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδελφος - ἀδελφός</font>\n<br><br>TDNT - , </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n340 fois dans 314 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (39)</li>\n<li>Marc (20)</li>\n<li>Luc (24)</li>\n<li>Jean (14)</li>\n<li>Actes (56)</li>\n<li>Romains (19)</li>\n<li>1 Corinthiens (37)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (11)</li>\n<li>Éphésiens (2)</li>\n<li>Philippiens (9)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (19)</li>\n<li>2 Thessaloniciens (9)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Philémon (4)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (19)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (15)</li>\n<li>3 Jean (3)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G81":"<h1>adelphotes</h1>\n<p>Strong n° 81 <i>Prononciation [ad-el-fot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fraternité, bonté fraternelle</li>\n<li>une famille de frères, une fraternité, la communauté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδελφότης</b> <b>ητος (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> réunion de frères, NT. <i>1Petr. 2, 17 ;</i><br><b> 2</b> affection fraternelle, SPT. <i>1Macc. 12, 10 ;</i><br><b> 3</b> <i>titre d’honneur</i> (votre Fraternité) SYN. <i>Ep. 72, 1436 a Migne</i>.<p><b>Étym</b>. ἀδελφός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδελφοτης - ἀδελφότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (2) => <a class=\"ref\" data-r=\"1PE2.17;5.9\">1 Pierre 2.17 ; 5.9</a></li>\n</ul>\n</td></tr>\n</table>","G82":"<h1>adelos</h1>\n<p>Strong n° 82 <i>Prononciation [ad'-ay-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non manifesté, indistinct, incertain, obscur, confus, non reconnaissable, non signalé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄδηλος</b> <b>ἄ·δηλος, ος, ον :<br> 1</b> qui ne se montre pas, qu’on ne voit pas, invisible, <i>en parl. de pers</i>. XÉN. <i>Cyr. 6, 3, 6 ; en parl. de choses :</i> ἄδ. ἔχθρα, THC. <i>8, 108,</i> secrète inimitié ;<br><b> 2</b> qui ne laisse rien voir, qui ne trahit rien, impénétrable (visage, <i>etc</i>.) EUR. <i>Or. 1318 ;</i><br><b> 3</b> obscur, incertain, inconnu, <i>en parl. de pers</i>. PLAT. <i>Leg. 874</i> a, <i>etc. ; en parl. de choses :</i> ἄδ. θάνατοι, SOPH. <i>O.R. 496,</i> mort donnée par une main inconnue ; ἄδηλόν (ἐστιν) ὅτι <i>ou</i> εἰ, ὅστις, ὅπως, <i>etc</i>. ATT. c’est une chose incertaine si, qui, comment, <i>etc. ;</i> ἄδηλον μή, PLAT. <i>Phæd. 91</i> d, il n’est pas sûr, que… ne, il est à craindre que ; <i>abs</i>. ἄδηλον ὄν, THC. <i>1, 2,</i> parce qu’on ne savait pas (si, <i>etc.) ; qqf. en accord avec le suj. :</i> οὐκ ἄδηλος ἦν ὁ κόσμος λυθησόμενος, ISOCR. <i>12, 116 Baiter-Sauppe,</i> il était visible que l’ordre allait être troublé.<br><i>● Cp</i>. -ότερος, XÉN. <i>Hell. 7, 5, 8 ;</i> ARSTT. <i>G.A. 5, 7</i>.<p><b>Étym</b>. ἀ, δῆλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-δηλος - ἄδηλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1) <a class=\"ref\" data-r=\"LUK11.44\">Luc 11.44</a></li>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO14.8\">1 Corinthiens 14.8</a></li>\n</ul>\n</td></tr>\n</table>","G83":"<h1>adelotes</h1>\n<p>Strong n° 83 <i>Prononciation [ad-ay-lot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>insécurité, précarité, fragilité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδηλότης</b> <b>ητος (ἡ)</b> obscurité, incertitude, POL. <i>5, 2, 3 ; 36, 4, 2 ;</i> NT. <i>1Tim. 6, 17 ;</i> PLUT. <i>Cæs. 7</i>.<p><b>Étym</b>. ἄδηλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-δηλοτης - ἀδηλότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI6.17\">1 Timothée 6.17</a></li>\n</ul>\n</td></tr>\n</table>","G84":"<h1>adelos</h1>\n<p>Strong n° 84 <i>Prononciation [ad-ay'-loce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'une façon incertaine, à l'aventure, sans savoir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδήλως</b> <i>adv</i>. en secret, en dissimulant, THC. <i>1, 92, etc</i>.<br><i>● Sup</i>. -ότατα, THC. <i>7, 50</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδηλως - ἀδήλως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO9.26\">1 Corinthiens 9.26</a></li>\n</ul>\n</td></tr>\n</table>","G85":"<h1>ademoneo</h1>\n<p>Strong n° 85 <i>Prononciation [ad-ay-mon-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être troublé, grande détresse ou angoisse, dépression, inquiet, se tourmenter</li>\n<li>des trois mots Grecs (, , ) du N.T, celui-ci est le plus fort pour « dépression ».</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδημονέω</b> <b>ἀδημονέω-ῶ</b>, (<i>seul. prés. et ao., inf. et partic</i>.) se tourmenter, HPC. <i>563, 5 ;</i> PLAT. <i>Theæt. 175</i> d, <i>etc. ;</i> ἀδημονῆσαι τὰς ψυχάς, XÉN. <i>Hell. 4, 4, 3,</i> avoir l’âme inquiète ; ἀδημονεῖν τινι <i>ou</i> ὑπό τινος, PLAT. <i>Phædr. 251</i> d, <i>etc. ;</i> ἐπί τινι, DH. <i>3, 70,</i> être inquiet de qqe ch.<p><b>Étym</b>. <i>inconnue</i> ou ἀδήμων.<br><i><b><font color=\"darkorange\">Par.</font></b></i> ἀμηχανέω, ἀπορέω², ξενοπαθέω..</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδημονεω - ἀδημονέω</font>\n<br><br>vient d'un dérivé d'adeo (être saisi de dégoût)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT26.37\">Matthieu 26.37</a></li>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK14.33\">Marc 14.33</a></li>\n<li>Philippiens (1) => <a class=\"ref\" data-r=\"PHP2.26\">Philippiens 2.26</a></li>\n</ul>\n</td></tr>\n</table>","G86":"<h1>hades</h1>\n<p>Strong n° 86 <i>Prononciation [hah'-dace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>Hadès ou Pluton, le dieu des profondeurs de la terre, le monde souterrain</li>\n<li>Orcus, le monde du néant, le royaume de la mort</li>\n<li>usage ultérieur du mot : tombe, mort, enfer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ᾅδης</b> <i>v</i>. Ἅιδης.<b>ᾍδης</b> <i>v</i>. Ἅιδης.<br>\n➪ <font color=\"red\">Ἅιδης,</font> ᾍδης,</b> <i>d'où</i> <b>ᾅδης, ου,</b> <i>ion. et épq.</i> <b>Ἀΐδης</b> (ὁ) [ᾱͅ] <p><b>1</b> Hadès (Pluton) roi des enfers, H<small>OM</small>. <i>etc. ; épq.</i> εἰν Ἀΐδαο, <i>att.</i> ἐν ᾍδου (<i>s. e.</i> δόμῳ) dans la demeure d'Hadès, chez Hadès, <i>sans mouv. ;</i> παρ' ᾍδῃ, S<small>OPH</small>. <i>O.R. 972, m. sign. ; épq.</i> εἰς Ἀΐδαο, <i>att.</i> ἐς ᾍδου (<i>s. e.</i> οἶκον) dans la demeure d'Hadès, chez Hadès, <i>avec mouv. ;</i> παρ' ᾍδην, S<small>OPH</small>. <i>O.C. 1552, m. sign.</i> </p><p><b>2</b> <i>p. ext.</i> le séjour des morts, les enfers : εἰς ἀΐδην, A<small>NTH</small>. <i>11, 23 ;</i> ἐν τῷ ᾅδῃ, NT. <i>Luc. 16, 23,</i> aux enfers </p><p><b>3</b> <i>p. suite,</i> la mort : ᾅδ. πόντιος, E<small>SCHL</small>. <i>Ag. 667,</i> la mort dans les flots </p><p><big><b>➵</b></big> <i>Nomin. ion. et épq.</i> Ἀΐδης [ᾰῐ] I<small>L</small>. <i>5, 395, etc. ; postér.</i> [ᾱῐ] S<small>IM</small>. <small>AM</small>. <i>Iamb. fr. 1, 14 ; dor.</i> Ἀΐδας [ᾱῐᾱ] P<small>D</small>. <i>O. 9, 50 ;</i> E<small>SCHL</small>. <i>Suppl. 791 ;</i> S<small>OPH</small>. <i>O.C. 1690, etc. Voc. ion.</i> Ἀΐδη [⏑⏑‒] S<small>OPH</small>. <i>Tr. 1085 ;</i> A<small>NTH</small>. <i>7, 186, ou</i> [‒⏑⏑] A<small>NTH</small>. <i>7, 365, etc. ; voc. dor.</i> Ἀΐδα [⏑⏑‒] A<small>NTH</small>. <i>7, 710, etc.</i> — <i>Gén. épq.</i> Ἀΐδαο, I<small>L</small>. <i>5, 647 ;</i> H<small>ÉS</small>. <i>O. 153, etc., ou</i> Ἀΐδεω, <i>trisyll.</i> [⏑⏑‒] O<small>D</small>. <i>10, 542 ;</i> H<small>ÉS</small>. <i>Th. 311, etc. ; quadrisyll.</i> [‒⏑⏑‒] S<small>OL</small>. <i>Ep. 5 ;</i> A<small>NTH</small>. <i>6, 219, etc. ; gén. dor.</i> Ἀΐδα [δᾱ] P<small>D</small>. <i>O. 8, 50 ;</i> S<small>OPH</small>. <i>El. 137, etc.</i> — <i>Dat. ion.</i> Ἀΐδῃ, A. R<small>H</small>. <i>4, 1697 ;</i> A<small>NTH</small>. <i>6, 70, etc. ; dat. dor.</i> Ἀΐδᾳ, P<small>D</small>. <i>I. 1, 99,</i> S<small>OPH</small>. <i>O.C. 1572, etc.</i> — <i>Acc. ion.</i> Ἀΐδην, I<small>L</small>. <i>9, 568 ; acc. dor.</i> Ἀΐδαν, S<small>OPH</small>. <i>Ant. 822,</i> E<small>L</small>. <i>832, etc.</i> </p><p><i><b><font color=\"brown\">Étym.</font></b> :</i> ἀ, ἰδεῖν ; <i>litt.</i> « l'Invisible », <i>cf.</i> Ἄϊδος.</p></div>\n<br>\n<b><font color=\"red\">ἀ·ϊδής,</font> ής, ές</b> : <p><b>1</b> invisible, H<small>ÉS</small>. <i>Sc. 477</i> <br><b>2</b> qui ne voit pas, B<small>ACCH</small>. <i>46</i> </p><p><i><b><font color=\"brown\">Étym.</font></b> : </i>ἀ, ἰδεῖν.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αδης - ᾅδης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT11.23;16.18\">Matthieu 11.23 ; 16.18</a></li>\n<li>Luc (2) => <a class=\"ref\" data-r=\"LUK10.15;16.23\">Luc 10.15 ; 16.23</a></li>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT2.27,31\">Actes 2.27,31</a></li>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO15.55\">1 Corinthiens 15.55</a></li>\n<li>Apocalypse (4) => <a class=\"ref\" data-r=\"REV1.18;6.8;20.13,14\">Apocalypse 1.18 ; 6.8 ; 20.13,14</a></li>\n</ul>\n</td></tr>\n</table>","G87":"<h1>adiakritos</h1>\n<p>Strong n° 87 <i>Prononciation [ad-ee-ak'-ree-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>indistinctement, inintelligible</li>\n<li>sans aucun doute, ambiguïté ou incertitude, sans équivoque, sans discussion, impartial, non partisan</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδιάκριτος</b> <b>ἀ·διάκριτος, ος, ον</b> <font color=\"brown\">[ῐτ]</font> :<br><b>   I</b> <i>pass. :</i><br><b> 1</b> non séparé, mêlé, HPC. <i>Coac. 213 ;</i><br><b> 2</b> non décidé, LUC. <i>J. tr. 25 ;</i><br><b> 3</b> qu’on ne peut discerner, <i>d’où</i> indistinct, confus, inintelligible, POL. <i>15, 12, 9 ;</i><br><b>   II</b> <i>act</i>. qui ne distingue pas, qui ne fait pas de différence de, <i>gén</i>. DYSC. <i>Synt. 36, 3</i>.<br><i>● Cp</i>. -ώτερος, ARSTT. <i>Somn. 3</i>.<p><b>Étym</b>. ἀ, διακρίνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-διακριτος - ἀδιάκριτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1) <a class=\"ref\" href=\"r.php?v=LSS&r=JAS3.17\">Jacques 3.17</a</li>\n</ul>\n</td></tr>\n</table>","G88":"<h1>adialeiptos</h1>\n<p>Strong n° 88 <i>Prononciation [ad-ee-al'-ipe-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans fin, sans cesse, continuel, constamment, sans interruption, continu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδιάλειπτος</b> <b>ἀ·διάλειπτος, ος, ον</b>, non interrompu, T. LOCR. <i>98</i> e ; NT. <i>Rom. 9, 2</i>.<p><b>Étym</b>. ἀ, διαλείπω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-διαλειπτος - ἀδιάλειπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1) <a class=\"ref\" data-r=\"ROM9.2\">Romains 9.2</a></li>\n<li>2 Timothée (1) => <a class=\"ref\" data-r=\"2TI1.3\">2 Timothée 1.3</a></li>\n</ul>\n</td></tr>\n</table>","G89":"<h1>adialeiptos</h1>\n<p>Strong n° 89 <i>Prononciation [ad-ee-al-ipe'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans arrêt, sans discontinuer, sans cesse, continuellement, constamment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδιαλείπτως</b> <i>adv</i>. sans interruption, POL. <i>9, 3, 8 ;</i> SPT. <i>1Macc. 12, 11 ;</i> NT. <i>Rom. 1, 9</i>.<br><font color=\"darkblue\">Étym.</font></b></i> ἀδιάλειπτος.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-διαλειπτωος - ἀδιαλείπτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1) <a class=\"ref\" data-r=\"ROM1.9\">Romains 1.9</a></li>\n<li>1 Thessaloniciens (3) => <a class=\"ref\" data-r=\"1TH1.3;2.13;5.17\">1 Thessaloniciens 1.3 ; 2.13 ; 5.17</a></li>\n</ul>\n</td></tr>\n</table>","G90":"<h1>adiaphthoria</h1>\n<p>Strong n° 90 <i>Prononciation [ad-ee-af-thor-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>incorruptibilité, intégrité, état de ce qui n'est pas corrompu, mélangé\n<ol type=\"a\">\n<li>de l'esprit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδιαφθορία</b> <b>ας (ἡ)</b> absence de souillure, NT. <i>Tit. 2, 7 dout</i>.<p><b>Étym</b>. ἀδιάφθορος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-διαφθορια - ἀδιαφθορία</font>\n<br><br>Voir définition  voir aussi apthoria (af-thor-ee'ah) (TDNT , )</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>ἀδιαφθορία (adiaphthoria) est un terme grec trouvé 0 fois dans la Bible.</td></tr>\n</table>","G91":"<h1>adikeo</h1>\n<p>Strong n° 91 <i>Prononciation [ad-ee-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mauvaise action\n<ol type=\"a\">\n<li>agir injustement, méchamment, pécher</li>\n<li>être un criminel, avoir violé la loi, être injuste, coupable</li>\n<li>faire le mal, faire du tort à, nuire,</li>\n<li>faire souffrir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδικέω</b> <b>ἀδικέω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ἠδίκουν, <i>f</i>. ἀδικήσω, <i>ao</i>. ἠδίκησα, <i>pf</i>. ἠδίκηκα)</font> <font color=\"brown\">[ᾰῐ]</font> :<br><b>   I <i>intr</i>.<br> 1</b> être injuste, commettre une injustice, avoir un tort, être coupable, HH. <i>Cer. 368 ;</i> ATT. (PLAT. <i>Gorg. 474</i> b, <i>etc</i>.) ; τὸ ἀδικεῖν ἐστι τὸ βλάπτειν ἑκόντα παρὰ τὸν νόμον, ARSTT. <i>Rhet. 1, 10,</i> être injuste (ἀδικεῖν) c’est nuire volontairement, contrairement à la loi ; ἀδ. ἀδικίαν <i>ou</i> ἀδίκημα, PLAT. <i>Rsp. 344</i> c, <i>409</i> a, <i>etc</i>. commettre une injustice <i>ou</i> une faute ; ἀδ. πολλά, PLAT. <i>Conv. 188</i> b, <i>etc</i>. avoir beaucoup de torts ; οὐδὲν ἀδ. PLAT. <i>Conv. 188</i> a, n’avoir aucun tort ;<br><b> 2</b> <i>particul</i>. être coupable au regard de la loi, agir illégalement : Σωκράτης ἀδικεῖ ποιῶν… καὶ διδάσκων, PLAT. <i>Ap. 19</i> b, Socrate est coupable en faisant… et en instruisant ; ὁ ἀδικῶν, ATT. le délinquant, l’accusé ; ὁ ἀδικούμενος, ATT. le plaignant, l’accusateur ;<br><b>   II <i>tr</i>.<br> 1</b> faire tort à, nuire à : τινα, HDT. <i>1, 112, etc. ;</i> περί τινα, PLAT. <i>Leg. 854</i> e, à qqn ; περί τι, CIA. <i>2, 811 c, 154 (323 av. J.C., v. Meisterh. p. 181, 45</i>) causer un dommage en ce qui regarde qqe ch. ; <i>avec double rég. :</i> τί τινα, ATT. (PLAT. <i>Theæt. 174</i> c, <i>Prot. 310</i> d, <i>etc</i>.) ; τινα περί τινος, PLAT. <i>Leg. 854</i> e ; τινα εἴς τι, ARSTT. <i>Rhet. 2, 12, 15,</i> à qqn en qqe eh. ; τὰ μέγιστα, τὰ ἔσχατα ἀδ. τινα, ATT. causer les plus grands dommages à qqn ; <i>au pass. (f</i>. ἀδικήσομαι, <i>postér</i>. -ηθήσομαι) subir une injustice, un tort, un dommage, THC. <i>1, 77 ;</i> ὑπό τινος, LUC. <i>Tim. 38,</i> de la part de qqn ; εἴς τι, EUR. <i>Med. 265,</i> en qqe ch. ; μεγάλα ἀδικεῖσθαι, ESCHN. <i>65, 35,</i> subir de grands dommages ;<br><b> 2</b> <i>au sens matér</i>. gâter, endommager, avarier, THC. <i>2, 71, etc.,</i> XÉN. <i>Eq. 6, 3</i>.<p><b>➼</b> <i>Prés. au sens du pf</i>. « j’ai commis une faute », <i>d’où</i> « je suis coupable », ANT. <i>4, δ, 9 Baiter-Sauppe ;</i> XÉN. <i>An. 7, 7, 31 ;</i> PLAT. <i>Rsp. 359</i> a, <i>etc. Prés. éol. 3 sg</i>. ἀδικήει, SAPPH. <i>1, 20. Impf. ion</i>. ἠδίκεον, HDT. <i>1, 121. Fut. moy</i>. ἀδικήσομαι, <i>au sens pass</i>. EUR. <i>I.A. 1437 ;</i> THC. <i>5, 56, etc. Fut. pass</i>. -ηθήσομαι, APD. <i>1, 9, 23. Au lieu du part. pf. pass</i>. ἀδικειμένος <i>dor. p</i>. ἠδικημένος, <i>v</i>. ἀδικείμενος.</p><p><b>Étym</b>. ἄδικος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδικεω - ἀδικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 23 versets de 9 livres bibliques (NT).\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Colossiens (2)</li>\n<li>Philémon (1)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G92":"<h1>adikema</h1>\n<p>Strong n° 92 <i>Prononciation [ad-eek'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire le mal, iniquité, délit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδίκημα</b> <b>ατος (τὸ)</b> <font color=\"brown\">[ᾰῐ]</font> :<br><b> 1</b> injustice, tort, faute, HDT. <i>1, 2, etc. ;</i> ATT. : πρός τινα, DÉM. <i>476, 6,</i> envers qqn ; ἀδ. τῶν νόμων, DÉM. <i>586, 11,</i> tort envers la loi : ἐν ἀδικήματι θέσθαι τι, THC. <i>1, 35, ou</i> θεῖναί τι, DÉM. <i>188, 19,</i> faire un crime de qqe ch. à qqn ; <i>particul</i>. délit, <i>p. opp. à</i> ἁμάρτημα, simple faute, <i>et à</i> ἀτύχημα, cas de force majeure, ARSTT. <i>Rhet. 1, 13, 3 ;</i><br><b> 2</b> <i>particul</i>. bien mal acquis, PLAT. <i>Rsp. 365</i> e, <i>Leg. 906</i> d.<p><b>Étym</b>. ἀδικέω.<br><font color=\"darkorange\">Par.</font></b></i> ἁμάρτημα, ἀτύχημα.<br><i><b><font color=\"red\">Ant.</font></b></i> δικαίωμα.<br><i><b><font color=\"darkorange\">Par.</font></b></i> ἅρπασμα.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδικημα - ἀδίκημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT18.14;24.20\">Actes 18.14 ; 24.20</a></li>\n<li>Apocalypse (1) => <a class=\"ref\" data-r=\"REV18.5\">Apocalypse 18.5</a></li>\n</ul>\n</td></tr>\n</table>","G93":"<h1>adikia</h1>\n<p>Strong n° 93 <i>Prononciation [ad-ee-kee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'injustice, d'un juge, tort, faute</li>\n<li>la complexité d'un cœur ou d'une vie</li>\n<li>violation volontaire de la loi et la justice</li>\n<li>iniquité, méchanceté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδικία</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾰδῐ]</font> injustice, tort, faute, HDT. <i>4, 1 ;</i> ATT. ; <i>au pl</i>. PLAT. <i>Phæd. 88</i> a, <i>etc. ;</i> τῆς πόλεως, DÉM. <i>24, 142 Baiter-Sauppe,</i> envers l’État ; περί τινα, XÉN. <i>Cyr. 8, 8, 7,</i> envers qqn ; ἀδικίης (<i>ion</i>.) ἄρχειν, HDT. <i>1, 130, etc</i>. être l’agresseur, l’offenseur ; <i>cf</i>. ἄδικος.<p><b>Étym</b>. ἄδικος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδικια - ἀδικία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 24 versets de 12 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (7)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G94":"<h1>adikos</h1>\n<p>Strong n° 94 <i>Prononciation [ad'-ee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descriptif de celui qui viole ou a violé la justice\n<ol type=\"a\">\n<li>injuste, méchant</li>\n<li>pécheur, coupable</li>\n<li>celui qui agit frauduleusement avec les autres, trompeur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄδικος</b> <b>ἄ·δικος, ος, ον</b> <font color=\"brown\">[ᾰῐ]</font> :<br><b>   I</b> qui ne fait pas ce qu’il doit, <i>d’où :</i><br><b> 1</b> injuste, qui fait tort : ἔς τινα, HDT. <i>2, 119, etc. ;</i> περί τινα, XÉN. <i>Cyr. 8, 8, 6, etc. ;</i> πρός τινα, ATT. injuste envers qqn ; τὸ ἄδ., τὰ ἄδ. ATT. l’injustice, l’injuste ; χεῖρες ἄδ. ATT. agression injuste ; ἄρχειν χειρῶν ἀδίκων, XÉN. <i>Cyr. 1, 5, 13 ;</i> ANT. <i>126, 6 ;</i> ἄρχειν ἀδίκων, EL. <i>V.H. 1, 14,</i> être agresseur ; ἄδ. πλοῦτος, ISOCR. <i>10</i> d, fortune mal acquise ;<br><b> 2</b> indocile, rétif : ἄδ. ἵππος, XÉN. <i>Cyr. 2, 2, 26,</i> cheval rétif ; ἄδ. γνάθος, XÉN. <i>Eq. 3, 5,</i> bouche dure, <i>en parl. d’un cheval ;</i><br><b>   II</b> sans jugement : ἄδ. ἡμέρα, LUC. <i>Lex. 6,</i> jour où l’on ne rend pas la justice (<i>lat</i>. dies nefastus).<br><i>● Cp</i>. -ώτερος, HÉS. <i>O. 174 ;</i> THC. <i>3, 42 et 63 ;</i> XÉN. <i>Hell. 2, 1, 15, etc. ;</i> PLAT. <i>Rsp. 610</i> c, <i>etc.</i> <i>● Sup</i>. -ώτατος, SOPH. <i>Tr. 1011 ;</i> THC. <i>6, 39 ;</i> XÉN. <i>Hell. 2, 3, 21 ;</i> PLAT. <i>Prot. 327</i> c, <i>etc</i>.<p><b>Étym</b>. ἀ, δίκη.<br><font color=\"red\">Ant.</font></b></i> ὅσιος.<br><i><b><font color=\"darkorange\">Par.</font></b></i> ἀσεβής, ἀνόσιος , ἄφιλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδικος - ἄδικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (4)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G95":"<h1>adikos</h1>\n<p>Strong n° 95 <i>Prononciation [ad-ee'-koce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>injustement, lorsqu'on n'a pas commis de faute</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδίκως</b> <font color=\"brown\">[ᾰῐ]</font> <i>adv. :</i><br><b> 1</b> injustement, HH. <i>Merc. 316 ;</i> HDT. <i>6, 137 ;</i> PLAT. <i>Leg. 743</i> b ;<br><b> 2</b> sans droit, sans raison : οὐκ ἀδ. PLAT. <i>Phæd. 72</i> a, à bon droit, avec raison.<br><i>● Sup</i>. -ώτατα, XÉN. <i>Hell. 5, 4, 24</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-δικωος - ἀδίκως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE2.19\">1 Pierre 2.19</a></li>\n</ul>\n</td></tr>\n</table>","G96":"<h1>adokimos</h1>\n<p>Strong n° 96 <i>Prononciation [ad-ok'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>refusé à l'épreuve, non approuvé, non mis à l'essai, qui n'a pas fait ses preuves\n<ol type=\"a\">\n<li>utilisé pour monnaie et poids</li>\n</ol>\n</li>\n<li>celui qui ne prouve pas ce qu'il devrait\n<ol type=\"a\">\n<li>faux, réprouvé, disqualifié</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδόκιμος</b> <b>ἀ·δόκιμος, ος, ον</b> <font color=\"brown\">[ῐ]</font> :<br><b> 1</b> de mauvais aloi (monnaie) PLAT. <i>Leg. 742</i> a ;<br><b> 2</b> réformé (cheval), ARSTT. <i>Ath. 49, 1 ;</i><br><b> 3</b> <i>p. suite,</i> vil, EUR. <i>Tr. 497 ;</i> PLAT. <i>Leg. 829</i> d, <i>etc. ; d’où</i> méprisé, XÉN. <i>Lac. 3, 3, etc</i>.<p><b>➼</b> <i>Fém. pl.,</i> ἀδόκιμαι, CIA. <i>2, 808 b, 54 (326 av. J.C., v. Meisterh. p. 116, § 58, 3)</i>.</p><p><font color=\"darkblue\">Étym.</font></b></i> ἀ, δόκιμος.<br><i><b><font color=\"red\">Ant.</font></b></i> δόκιμος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-δοκιμος - ἀδόκιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM1.28\">Romains 1.28</a></li>\n<li>1 Corinthiens (1) => <a class=\"ref\" data-r=\"1CO9.27\">1 Corinthiens 9.27</a></li>\n<li>2 Corinthiens (3) => <a class=\"ref\" data-r=\"2CO13.5,6,7\">2 Corinthiens 13.5,6,7</a></li>\n<li>2 Timothée (1) => <a class=\"ref\" data-r=\"2TI3.8\">2 Timothée 3.8</a></li>\n<li>Tite (1) => <a class=\"ref\" data-r=\"TIT1.16\">Tite 1.16</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB6.8\">Hébreux 6.8</a></li>\n</ul>\n</td></tr>\n</table>","G97":"<h1>adolos</h1>\n<p>Strong n° 97 <i>Prononciation [ad'-ol-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pur, ingénu\n<ol type=\"a\">\n<li>choses : sans mélange, inaltéré, pur, non altéré, non sophistiqué</li>\n<li>personnes : sans intention malhonnête, ingénu, sans fraude, franc, loyal</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄδολος</b> <b>ἄ·δολος, ος, ον</b>, sans fraude, franc, loyal, <i>en parl. de choses (traité,</i> THC. <i>5, 18 ; paix,</i> AR. <i>Lys. 168 ; caresses,</i> ESCHL. <i>Ag. 95, etc.) ; particul. en parl. de liquides,</i> non sophistiqué, non altéré, pur, DIOSC. <i>1, 79 ;</i> DAMOCR. (GAL. <i>13, 848</i>) ; GEOP. <i>20, 8 ; fig. en parl. de l’âme,</i> EUR. <i>Suppl. 1029 ; d’une doctrine,</i> NT. <i>1Petr. 2, 2</i>.<br><i>● Cp</i>. -ώτερος, ARSTD. <i>t. 1, 460 ;</i> <i>● Sup</i>. -ώτατος, SYN.<p><b>Étym</b>. ἀ, δόλος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-δολος - ἄδολος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE2.2\">1 Pierre 2.2</a></li>\n</ul>\n</td></tr>\n</table>","G98":"<h1>Adramuttenos</h1>\n<p>Strong n° 98 <i>Prononciation [ad-ram-oot-tay-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Adramytte (Angl. Adramyttium) = « Je demeurerai dans la mort »\n<ol><li>Adramytte, un port de mer de Mysie, au fond du golfe protégé par l'île de Lesbos</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αδραμυττηνος - Ἀδραμυττηνός</font>\n<br><br>vient de Adramutteion (un lieu d'Asie Mineure)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT27.2\">Actes 27.2</a></li>\n</ul>\n</td></tr>\n</table>","G99":"<h1>Adrias</h1>\n<p>Strong n° 99 <i>Prononciation [ad-ree'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Adriatique (Angl. Adriatic) = « sans bois »\n<ol><li>Mer Adriatique, Adrias, la mer entre la Grèce et l'Italie</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀδριάς</b> <b>άδος</b>, <i>adj. f</i>. de l’Adriatique, DP. <i>92</i>.<p><b>Étym</b>. Ἀδρίας.<b>Ἀδρίας</b> <b>ου (ὁ)</b> la mer Adriatique, LYS. <i>32, 25 Baiter-Sauppe, etc. ; rar. sans article,</i> ANTH. <i>11, 247 ;</i> SCYMN. <i>375 ; avec l’art. dans une inscr. att</i>. CIA. <i>2, 809 a, 176 (325 av. J.C.) v. Meisterh. p. 186, 16</i>.</p><p><b>➼</b> <i>Gén</i>. -α, POL. <i>3, 47</i><br><i>Ion</i>. -ίης, HDT. <i>1, 163, etc</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αδριας - Ἀδρίας</font>\n<br><br>vient de Adria (lieu près de ses côtes)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT27.27\">Actes 27.27</a></li>\n</ul>\n</td></tr>\n</table>"};
